  async cancelBooking(
    bookingId: string,
    data: { cancellationReason?: string },
    requester: { _id: string; userType: string }
  ): Promise<IBooking> {
    const booking =
      requester.userType === 'admin'
        ? await this.getById(bookingId)
        : await this.getById(bookingId, requester._id);

    if (booking.status === 'cancelled') {
      return booking;
    }

    this.enforceUserCancellationWindow(booking, requester);

    const updated = await this.bookingRepository.update(
      { _id: bookingId },
      {
        status: 'cancelled',
        paymentStatus: 'refunded',
        cancellationReason: data.cancellationReason || 'Cancelled by user',
        cancelledAt: getTodayYyyymmdd(),
        lifecycle: this.buildLifecyclePatch(booking.lifecycle, {
          cancelled: {
            reason: data.cancellationReason || 'Cancelled by user',
          },
          refunded: {
            reason: data.cancellationReason || 'Cancelled by user',
          },
        }),
      }
    );

    if (!updated) {
      throw new AppError({
        status: 500,
        code: 'UPDATE_FAILED',
        message: 'Failed to cancel booking',
      });
    }

    try {
      await this.refundBookingAmountToWallet(booking);
    } catch (error) {
      console.error('Failed to refund cancelled booking amount to wallet:', error);
    }

    if (booking.specialistId) {
      try {
        await this.notificationService.createSpecialistAppointmentCancelledNotification(
          booking.specialistId,
          bookingId,
          {
            bookingType: booking.bookingType,
            bookingDate: booking.bookingDate,
            bookingTime: booking.bookingTime,
            cancellationReason: data.cancellationReason || 'Cancelled by user',
            userId: booking.userId,
          }
        );
      } catch (error) {
        console.error(
          'Failed to create specialist cancellation notification:',
          error
        );
      }
    }

    if (
      booking.followUp?.isFollowUp &&
      booking.followUp.parentConsultationId &&
      booking.status !== 'completed'
    ) {
      try {
        const parentConsultation = await this.bookingRepository.findById(
          booking.followUp.parentConsultationId
        );

        if (parentConsultation) {
          await this.bookingRepository.update(
            { _id: parentConsultation._id },
            {
              followUp: {
                ...(parentConsultation.followUp || {}),
                isFollowUp: false,
                completedAt: parentConsultation.followUp?.completedAt,
                eligibilityExpiresAt:
                  parentConsultation.followUp?.eligibilityExpiresAt,
                benefitUsed: false,
              },
            }
          );
        }
      } catch (error) {
        console.error('Failed to restore parent follow-up benefit:', error);
      }
    }

    const finalBooking = await this.ensureCancelledBookingPaymentStatus(updated);

    await this.bookingReminderScheduler.clearBookingReminders(finalBooking._id!);

    if (booking.slotId) {
      try {
        const slot = await this.slotRepository.findById(booking.slotId);
        if (slot?.currentBookings && slot.currentBookings > 0) {
          await this.slotService.decrementBookingCount(booking.slotId);
        }
      } catch (error) {
        console.error('Failed to decrement slot booking count:', error);
      }
    }

    return cancelBookingMeet({
      booking: finalBooking,
      reason: finalBooking.cancellationReason,
      bookingRepository: this.bookingRepository,
    });
  }

  async rescheduleBooking(
    bookingId: string,
    data: {
      slotId: string;
      bookingDate?: string;
      bookingTime?: string;
      serviceMode?: IBooking['serviceMode'];
      serviceAddress?: IBooking['serviceAddress'];
      consultationMode?: IBooking['consultationMode'];
      notes?: string;
    },
    requester: { _id: string; userType: string }
  ): Promise<IBooking> {
    const booking =
      requester.userType === 'admin'
        ? await this.getById(bookingId)
        : await this.getById(bookingId, requester._id);

    if (booking.status === 'cancelled') {
      throw new AppError({
        status: 400,
        code: 'BOOKING_CANCELLED',
        message: 'Cancelled bookings cannot be rescheduled',
      });
    }

    if (booking.status === 'completed') {
      throw new AppError({
        status: 400,
        code: 'BOOKING_COMPLETED',
        message: 'Completed bookings cannot be rescheduled',
      });
    }

    const nextSlot = await this.slotService.getById(data.slotId);
    const nextBookingDate = data.bookingDate || nextSlot.date;
    const nextBookingTime = data.bookingTime || nextSlot.startTime;

    await this.validateBookingDateAndSlot(nextBookingDate, data.slotId, {
      allowCurrentSlotId: booking.slotId,
    });

    const oldSlotId = booking.slotId;
    const newSlotId = data.slotId;
    const slotChanged = !!newSlotId && newSlotId !== oldSlotId;

    if (slotChanged) {
      await this.slotService.incrementBookingCount(newSlotId);
      try {
        if (oldSlotId) {
          const oldSlot = await this.slotRepository.findById(oldSlotId);
          if (oldSlot?.currentBookings && oldSlot.currentBookings > 0) {
            await this.slotService.decrementBookingCount(oldSlotId);
          }
        }
      } catch (error) {
        await this.slotService.decrementBookingCount(newSlotId);
        throw error;
      }
    }

    const updatePayload: UpdateBookingRequest = {
      slotId: newSlotId,
      bookingDate: nextBookingDate,
      bookingTime: nextBookingTime,
      notes: data.notes ?? booking.notes,
    };

    if (data.serviceMode) {
      updatePayload.serviceMode = data.serviceMode;
    }

    if (data.serviceAddress) {
      updatePayload.serviceAddress = data.serviceAddress;
    }

    if (data.consultationMode) {
      updatePayload.consultationMode = data.consultationMode;
    }

    const updated = await this.bookingRepository.update(
      { _id: bookingId },
      {
        ...updatePayload,
        lifecycle: this.buildLifecyclePatch(booking.lifecycle, {
          rescheduled: true,
        }),
      }
    );

    if (!updated) {
      if (slotChanged) {
        await this.slotService.decrementBookingCount(newSlotId);
        if (oldSlotId) {
          await this.slotService.incrementBookingCount(oldSlotId);
        }
      }

      throw new AppError({
        status: 500,
        code: 'UPDATE_FAILED',
        message: 'Failed to reschedule booking',
      });
    }

    if (updated.status === 'confirmed') {
      await this.bookingReminderScheduler.scheduleBookingReminders(updated);
      return syncBookingMeet({
        booking: updated,
        bookingRepository: this.bookingRepository,
        userRepository: this.userRepository,
        specialistRepository: this.specialistRepository,
        slotRepository: this.slotRepository,
      });
    }

    return updated;
  }

  async retryBookingPayment(
    bookingId: string,
    requester: { _id: string; userType: string; corporateId?: string; pharmacyId?: string },
    options: RetryBookingPaymentRequest = {}
  ): Promise<BookingPaymentInitResponse> {
    const booking = await this.getById(bookingId);

    const canAccess =
      requester.userType === 'admin' ||
      (
        requester.userType === 'pharmacy' &&
        requester.pharmacyId &&
        String(booking.pharmacyId) === String(requester.pharmacyId)
      ) ||
      String(booking.userId) === String(requester._id);

    if (!canAccess) {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'You are not allowed to retry payment for this booking',
      });
    }

    if (booking.status === 'cancelled') {
      throw new AppError({
        status: 400,
        code: 'BOOKING_CANCELLED',
        message: 'Cannot retry payment for a cancelled booking',
      });
    }

    if (booking.paymentStatus === 'paid') {
      throw new AppError({
        status: 400,
        code: 'BOOKING_ALREADY_PAID',
        message: 'Booking is already paid',
      });
    }

    let baseAmount = booking.originalPrice ?? booking.price;
    let discountAmount = Math.max(0, (booking.originalPrice ?? booking.price) - booking.price);
    let couponCode = options.couponCode;
    let walletDeductedAmount = 0;

    if (booking.paymentTransactionId) {
      const previousPayment = await this.paymentRepository.findById(
        booking.paymentTransactionId
      );

      if (previousPayment) {
        if (previousPayment.status === 'paid') {
          throw new AppError({
            status: 400,
            code: 'BOOKING_ALREADY_PAID',
            message: 'Booking is already paid',
          });
        }

        baseAmount = previousPayment.baseAmount;
        if (!couponCode) {
          discountAmount = previousPayment.discountAmount;
          couponCode = previousPayment.couponCode;
        }
        walletDeductedAmount = Number(previousPayment.notes?.walletDeductedAmount || 0);
      }
    }

    if (options.couponCode) {
      const bookingCouponType = booking.bookingType === 'package' ? 'package' : 'consultation';
      const couponResult = await this.resolveRetryBookingCoupon({
        booking,
        bookingType: bookingCouponType,
        grossAmount: baseAmount,
        requesterCorporateId:
          requester.userType === 'admin'
            ? booking.corporateId
            : requester.corporateId,
        couponCode: options.couponCode,
      });

      discountAmount = couponResult.discountAmount;
      couponCode = couponResult.couponCode;
    }

    await this.validateWalletIfRequested(
      booking.userId,
      options.useWalletBalance
    );

    const grossAmount = Math.max(0, baseAmount - discountAmount);
    let extraWalletDeductedAmount = 0;
    if (options.useWalletBalance) {
      const walletRoom = Math.max(0, grossAmount - walletDeductedAmount);
      if (walletRoom > 0) {
        extraWalletDeductedAmount = await this.deductWalletForBooking({
          userId: booking.userId,
          bookingId: booking._id!,
          amountToDeductFromWallet: walletRoom,
          useWalletBalance: true,
        });
      }
    }

    const totalWalletDeductedAmount =
      walletDeductedAmount + extraWalletDeductedAmount;
    const payableAfterWallet = Math.max(0, grossAmount - totalWalletDeductedAmount);

    if (payableAfterWallet <= 0) {
      const directPaidTransaction =
        await this.paymentService.createDirectPaidTransaction({
          userId: booking.userId,
          context: 'booking',
          contextId: booking._id!,
          baseAmount,
          discountAmount,
          finalAmount: 0,
          couponCode,
          notes: {
            bookingType: booking.bookingType,
            reason:
              totalWalletDeductedAmount > 0
                ? 'wallet_covered_amount'
                : 'zero_payable_amount',
            retryOfBookingId: booking._id!,
            walletDeductedAmount: totalWalletDeductedAmount,
          },
        });

      const paidBooking = await this.bookingRepository.update(
        { _id: booking._id! },
        {
          paymentStatus: 'paid',
          paymentTransactionId: directPaidTransaction._id!,
          status: booking.status === 'pending' ? 'confirmed' : booking.status,
          lifecycle: this.buildLifecyclePatch(booking.lifecycle, {
            paid: { amount: grossAmount },
            confirmed: booking.status === 'pending' ? true : undefined,
          }),
        }
      );

      if (couponCode) {
        const coupon = await this.couponService.getByCode(couponCode);
        await this.couponService.incrementUsage(coupon._id!);
      }

      const settledBooking = paidBooking || booking;
      if (settledBooking.status === 'confirmed') {
        await this.bookingReminderScheduler.scheduleBookingReminders(
          settledBooking
        );
        const bookingWithMeeting = await syncBookingMeet({
          booking: settledBooking,
          bookingRepository: this.bookingRepository,
          userRepository: this.userRepository,
          specialistRepository: this.specialistRepository,
          slotRepository: this.slotRepository,
        });
        await this.sendPaidBookingEmailNotification(bookingWithMeeting);

        return {
          booking: bookingWithMeeting,
          paymentRequired: false,
          walletDeductedAmount: totalWalletDeductedAmount,
        };
      }

      await this.sendPaidBookingEmailNotification(settledBooking);

      return {
        booking: settledBooking,
        paymentRequired: false,
        walletDeductedAmount: totalWalletDeductedAmount,
      };
    }

    const order = await this.paymentService.createOrder({
      userId: booking.userId,
      context: 'booking',
      contextId: booking._id!,
      baseAmount,
      discountAmount,
      finalAmount: payableAfterWallet,
      couponCode,
      notes: {
        bookingType: booking.bookingType,
        retryOfBookingId: booking._id!,
        walletDeductedAmount: totalWalletDeductedAmount,
      },
    });

    const updatedBooking = await this.bookingRepository.update(
      { _id: booking._id! },
      {
        paymentStatus: 'pending',
        paymentTransactionId: order.paymentRecord._id!,
        lifecycle: this.buildLifecyclePatch(booking.lifecycle, {
          paymentPending: { amount: payableAfterWallet },
        }),
      }
    );

    return {
      booking: updatedBooking || booking,
      paymentRequired: true,
      walletDeductedAmount: totalWalletDeductedAmount,
      payment: {
        paymentTransactionId: order.paymentRecord._id!,
        razorpayOrderId: order.razorpayOrder.id,
        razorpayKeyId: order.razorpayKeyId,
        amount: payableAfterWallet,
        currency: order.razorpayOrder.currency,
        baseAmount,
        discountAmount,
        couponCode,
        walletDeductedAmount: totalWalletDeductedAmount,
      },
    };
  }
}

import { Connection, Model, Schema } from 'mongoose';
import { AuthorityError } from '../types';

// Only the approved read adapter consumes this factory; importing it registers no model.
const canonicalId = { type: String, required: true, match: /^[0-9a-f]{24}$/, immutable: true };
const digest = { type: String, required: true, match: /^[0-9a-f]{64}$/ };
const positive = { type: Number, required: true, min: 1, validate: Number.isSafeInteger };
const date = { type: Date, required: true };
const capability = { type: String, required: true, enum: ['pharmacy.prescription.review', 'lab.report.release'] };
const state = { type: String, required: true, enum: ['active', 'suspended', 'revoked'] };
const embedded = { _id: false, strict: 'throw' as const };
const options = { timestamps: true, strict: 'throw' as const, versionKey: false as const, autoIndex: false, autoCreate: false };
const bounded = (values: unknown[]) => Array.isArray(values) && values.length >= 1 && values.length <= 100;
const base = { _id: canonicalId, schemaVersion: { type: Number, required: true, enum: [1], immutable: true }, revision: positive };

export interface AuthorityModels {
  readonly organization: Model<Record<string, unknown>>;
  readonly membership: Model<Record<string, unknown>>;
  readonly eligibility: Model<Record<string, unknown>>;
  readonly decision: Model<Record<string, unknown>>;
}
const registered = new WeakMap<Connection, AuthorityModels>();
export function createAuthorityModels(connection: Connection): AuthorityModels {
  const previous = registered.get(connection);
  if (previous) return previous;
  const names = ['BusinessAuthorityOrganization', 'BusinessStaffMembership', 'BusinessProfessionalEligibility', 'BusinessAuthorityDecision'];
  if (names.some(name => connection.models[name])) throw new AuthorityError('AUTHORITY_NOT_READY');
  const branch = new Schema({ branchId: canonicalId, state, revision: positive }, embedded);
  const grant = new Schema({ branchId: canonicalId, capability, grantDecisionId: canonicalId }, embedded);
  const evidence = new Schema({ evidenceVersionId: canonicalId, evidenceSha256: digest }, embedded);
  const organization = new Schema<Record<string, unknown>>({
    ...base, kind: { type: String, required: true, enum: ['pharmacy', 'lab'] },
    sourceBusinessId: canonicalId, state, sourceFingerprint: digest, mappingDecisionId: canonicalId,
    branches: { type: [branch], required: true, validate: bounded },
  }, options);
  organization.index({ kind: 1, sourceBusinessId: 1 }, { unique: true });
  const membership = new Schema<Record<string, unknown>>({
    ...base, organizationId: canonicalId, actorId: canonicalId, state, validFrom: date, expiresAt: date,
    grants: { type: [grant], required: true, validate: bounded },
  }, options);
  membership.index({ organizationId: 1, actorId: 1 }, { unique: true });
  const eligibility = new Schema<Record<string, unknown>>({
    ...base, organizationId: canonicalId, actorId: canonicalId,
    profession: { type: String, required: true, enum: ['pharmacist', 'lab_signatory'] },
    state: { type: String, required: true, enum: ['verified', 'suspended', 'revoked'] },
    validFrom: date, expiresAt: date, verificationDecisionId: canonicalId,
    evidenceVersionId: canonicalId, evidenceSha256: digest,
  }, options);
  eligibility.index({ organizationId: 1, actorId: 1, profession: 1 }, { unique: true });
  // Explicit optional union fields, with exact decision-kind validation in the sole rule evaluator.
  const payload = new Schema({
    organizationId: canonicalId,
    organizationRevision: { type: Number, min: 1, validate: Number.isSafeInteger },
    kind: { type: String, enum: ['pharmacy', 'lab'] },
    sourceBusinessId: { type: String, match: /^[0-9a-f]{24}$/ },
    sourceFingerprint: { type: String, match: /^[0-9a-f]{64}$/ },
    branches: { type: [branch], default: undefined, validate: bounded },
    actorId: { type: String, match: /^[0-9a-f]{24}$/ },
    membershipId: { type: String, match: /^[0-9a-f]{24}$/ },
    membershipRevision: { type: Number, min: 1, validate: Number.isSafeInteger },
    eligibilityId: { type: String, match: /^[0-9a-f]{24}$/ },
    eligibilityRevision: { type: Number, min: 1, validate: Number.isSafeInteger },
    validFrom: { type: Date }, expiresAt: { type: Date },
    // Grant entries have an optional decision ID for the professional scope payload.
    grants: { type: [new Schema({ branchId: canonicalId, capability, grantDecisionId: { type: String, match: /^[0-9a-f]{24}$/ } }, embedded)], default: undefined, validate: bounded },
    branchId: { type: String, match: /^[0-9a-f]{24}$/ },
    capability: { type: String, enum: ['pharmacy.prescription.review', 'lab.report.release'] },
    profession: { type: String, enum: ['pharmacist', 'lab_signatory'] },
    evidenceVersionId: { type: String, match: /^[0-9a-f]{24}$/ },
    evidenceSha256: { type: String, match: /^[0-9a-f]{64}$/ },
  }, embedded);
  // No mutation API is exposed. Immutability is defense in depth, not grant authenticity.
  const decision = new Schema<Record<string, unknown>>({
    _id: canonicalId, schemaVersion: { type: Number, required: true, enum: [1], immutable: true },
    organizationId: canonicalId, operationId: canonicalId,
    decisionKind: { type: String, required: true, enum: ['business_mapped', 'membership_granted', 'professional_verified'], immutable: true },
    subjectActorId: { type: String, match: /^[0-9a-f]{24}$/, immutable: true },
    decidingActorId: canonicalId, decidedAt: { ...date, immutable: true },
    authorityGeneration: { ...digest, immutable: true }, payloadSha256: { ...digest, immutable: true },
    payload: { type: payload, required: true, immutable: true },
    evidence: { type: [evidence], required: true, validate: bounded, immutable: true },
  }, options);
  decision.index({ organizationId: 1, operationId: 1 }, { unique: true });
  const models = Object.freeze({
    organization: connection.model(names[0], organization, 'business_authority_organizations'),
    membership: connection.model(names[1], membership, 'business_staff_memberships'),
    eligibility: connection.model(names[2], eligibility, 'business_professional_eligibility'),
    decision: connection.model(names[3], decision, 'business_authority_decisions'),
  });
  registered.set(connection, models);
  return models;
}

import { ClientSession, Connection, Model, Types, mongo } from 'mongoose';
import { createAuthorityModels } from '../model';
import { AuthorityError, AuthorityFacts, AuthorityLookup, AuthorityReadiness, AuthorityReadPort } from '../types';
import { pharmacyFingerprint, validateEligibility, validateLookup, validateMembership, validateOrganization, validateReadiness, validateUser } from '../rules';

const version = { _id: 1, schemaVersion: 1, revision: 1, createdAt: 1, updatedAt: 1 };
const organizationProjection = { ...version, kind: 1, sourceBusinessId: 1, state: 1, sourceFingerprint: 1, mappingDecisionId: 1, branches: 1 };
const membershipProjection = { ...version, organizationId: 1, actorId: 1, state: 1, validFrom: 1, expiresAt: 1, grants: 1 };
const eligibilityProjection = { ...version, organizationId: 1, actorId: 1, profession: 1, state: 1, validFrom: 1, expiresAt: 1, verificationDecisionId: 1, evidenceVersionId: 1, evidenceSha256: 1 };
const decisionProjection = { _id: 1, schemaVersion: 1, organizationId: 1, operationId: 1, decisionKind: 1, subjectActorId: 1, decidingActorId: 1, decidedAt: 1, authorityGeneration: 1, payloadSha256: 1, payload: 1, evidence: 1, createdAt: 1, updatedAt: 1 };
const closed = async (): Promise<AuthorityReadiness> => Object.freeze({ ready: false });
const denied = (): never => { throw new AuthorityError('AUTHORITY_DENIED'); };
const single = (rows: readonly unknown[]): unknown => rows.length === 1 ? rows[0] : denied();

type ProjectionKind = 'legacyUser' | 'legacyPharmacy' | 'organization' | 'membership' | 'eligibility' | 'decision';
const timestampPath = (kind: ProjectionKind, path: string): boolean => {
  if (kind === 'legacyUser' || kind === 'legacyPharmacy') return false;
  if (path === 'createdAt' || path === 'updatedAt') return true;
  if ((kind === 'membership' || kind === 'eligibility') && (path === 'validFrom' || path === 'expiresAt')) return true;
  return kind === 'decision' && (path === 'decidedAt' || path === 'payload.validFrom' || path === 'payload.expiresAt');
};

// Closed projection paths only: never repair an authority ID/revision with BSON coercion.
function immutableProjection(value: unknown, kind: ProjectionKind, path = '', depth = 0): unknown {
  if (depth > 10) return denied();
  if (timestampPath(kind, path)) {
    if (!(value instanceof Date)) return denied();
    const epoch = value.getTime();
    if (!Number.isSafeInteger(epoch) || epoch < 0) return denied();
    return epoch;
  }
  if ((kind === 'legacyUser' || kind === 'legacyPharmacy') && path === '_id') {
    if (!(value instanceof Types.ObjectId)) return denied();
    return value.toHexString();
  }
  if (value instanceof Date || value instanceof Types.ObjectId) return denied();
  if (value === null || typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return value;
  if (Array.isArray(value)) {
    if (value.length > 100) return denied();
    return Object.freeze(value.map(v => immutableProjection(v, kind, `${path}[]`, depth + 1)));
  }
  if (!value || typeof value !== 'object' || ![Object.prototype, null].includes(Object.getPrototypeOf(value))) return denied();
  const entries = Object.entries(value);
  if (entries.length > 32) return denied();
  return Object.freeze(Object.fromEntries(entries.map(([k, v]) => [k, immutableProjection(v, kind, path ? `${path}.${k}` : k, depth + 1)])));
}

export class MongoBusinessAuthorityReadPort implements AuthorityReadPort {
  constructor(private readonly connection: Connection, private readonly readinessProvider: () => Promise<AuthorityReadiness> = closed) {}

  readiness(): Promise<AuthorityReadiness> { return this.readinessProvider(); }

  private snapshotSession(value: unknown): ClientSession {
    // Structural lookalikes never qualify. The instance must belong to this exact connection's driver/client.
    const DriverSession = mongo.ClientSession;
    if (typeof DriverSession !== 'function' || !(value instanceof DriverSession)) throw new AuthorityError('INVALID_TRANSACTION');
    const session = value as ClientSession;
    const internals = session as unknown as { client?: unknown; transaction?: { options?: { readConcern?: { level?: unknown } } } };
    if (internals.client !== this.connection.getClient() || !session.inTransaction() || internals.transaction?.options?.readConcern?.level !== 'snapshot') throw new AuthorityError('INVALID_TRANSACTION');
    return session;
  }

  private existingModel(name: 'User' | 'Pharmacy', collection: 'users' | 'pharmacies'): Model<unknown> {
    const result = this.connection.models[name];
    if (!result || result.db !== this.connection || result.collection.name !== collection) throw new AuthorityError('AUTHORITY_NOT_READY');
    return result as Model<unknown>;
  }

  async loadFacts(lookup: AuthorityLookup, transaction: unknown, now: number): Promise<AuthorityFacts> {
    validateLookup(lookup, now);
    const session = this.snapshotSession(transaction);
    const heldTransaction = (session as unknown as { transaction: unknown }).transaction;
    const acceptedGeneration = validateReadiness(await this.readiness());
    if (acceptedGeneration !== lookup.authorityGeneration) throw new AuthorityError('AUTHORITY_NOT_READY');
    const models = createAuthorityModels(this.connection);
    const read = async (model: Model<unknown>, filter: Record<string, unknown>, projection: Record<string, number>, kind: ProjectionKind): Promise<readonly unknown[]> => {
      this.snapshotSession(session);
      if ((session as unknown as { transaction: unknown }).transaction !== heldTransaction) throw new AuthorityError('INVALID_TRANSACTION');
      const rows = await model.find(filter).select(projection).session(session).limit(2).lean().exec();
      this.snapshotSession(session);
      if ((session as unknown as { transaction: unknown }).transaction !== heldTransaction) throw new AuthorityError('INVALID_TRANSACTION');
      if (!Array.isArray(rows) || rows.length > 2) return denied();
      return Object.freeze(rows.map(row => immutableProjection(row, kind)));
    };
    const user = single(await read(this.existingModel('User', 'users'), { _id: lookup.actorId, userType: 'user', isActive: true }, { _id: 1, userType: 1, isActive: 1 }, 'legacyUser'));
    validateUser(user, lookup);
    const organization = single(await read(models.organization, {
      _id: lookup.organizationId, state: 'active', branches: { $elemMatch: { branchId: lookup.branchId, state: 'active' } },
    }, organizationProjection, 'organization'));
    const org = validateOrganization(organization, lookup, now);
    if (org.kind !== 'pharmacy') throw new AuthorityError('AUTHORITY_MAPPING_UNAVAILABLE');
    const pharmacy = single(await read(this.existingModel('Pharmacy', 'pharmacies'), {
      _id: org.sourceBusinessId, isActive: true, isVerified: true, archivedAt: { $exists: false },
    }, { _id: 1, isActive: 1, isVerified: 1, archivedAt: 1, drugLicenseNumber: 1, drugLicenseDocumentUrl: 1 }, 'legacyPharmacy'));
    if (pharmacyFingerprint(pharmacy) !== org.sourceFingerprint) return denied();
    const memberships = await read(models.membership, {
      organizationId: lookup.organizationId, actorId: lookup.actorId, state: 'active', validFrom: { $lte: new Date(now) }, expiresAt: { $gt: new Date(now) },
      grants: { $elemMatch: { branchId: lookup.branchId, capability: lookup.capability } },
    }, membershipProjection, 'membership');
    const member = validateMembership(single(memberships), lookup, org, now);
    const selected = member.grants.filter(g => g.branchId === lookup.branchId && g.capability === lookup.capability);
    if (selected.length !== 1) return denied();
    const eligibility = await read(models.eligibility, {
      organizationId: lookup.organizationId, actorId: lookup.actorId, profession: 'pharmacist', state: 'verified',
      validFrom: { $lte: new Date(now) }, expiresAt: { $gt: new Date(now) },
    }, eligibilityProjection, 'eligibility');
    const eligible = validateEligibility(single(eligibility), lookup, now);
    const decision = (decisionId: string, decisionKind: string, subject = false) => read(models.decision, {
      _id: decisionId, organizationId: lookup.organizationId, decisionKind, authorityGeneration: acceptedGeneration,
      ...(subject ? { subjectActorId: lookup.actorId } : {}),
    }, decisionProjection, 'decision');
    const mappingDecisions = await decision(org.mappingDecisionId, 'business_mapped');
    const grantDecisions = await decision(selected[0].grantDecisionId, 'membership_granted', true);
    const verificationDecisions = await decision(eligible.verificationDecisionId, 'professional_verified', true);
    return Object.freeze({ user, organization, pharmacy, memberships, eligibility, mappingDecisions, grantDecisions, verificationDecisions });
  }
}

import { createHash } from 'crypto';
import {
  AuthorityDecision, AuthorityError, AuthorityFacts, AuthorityLookup,
  AuthorityRequest, AuthenticatedPerson, Branch, BusinessScope, Capability, Eligibility,
  EvidenceReference, GrantPayload, MappingPayload, Membership, Organization,
  StaffGrant, VerificationPayload,
} from './types';

type Data = Record<string, unknown>;
const id = (v: unknown): v is string => typeof v === 'string' && /^[0-9a-f]{24}$/.test(v);
const digest = (v: unknown): v is string => typeof v === 'string' && /^[0-9a-f]{64}$/.test(v);
const integer = (v: unknown): v is number => Number.isSafeInteger(v) && (v as number) > 0;
const time = (v: unknown): v is number => Number.isSafeInteger(v) && (v as number) >= 0 && (v as number) <= 8640000000000000;
const capability = (v: unknown): v is Capability => v === 'pharmacy.prescription.review' || v === 'lab.report.release';
const state = (v: unknown) => v === 'active' || v === 'suspended' || v === 'revoked';
const deny = (): never => { throw new AuthorityError('AUTHORITY_DENIED'); };
const check = (ok: unknown): void => { if (!ok) deny(); };
const data = (v: unknown): Data => {
  if (!v || typeof v !== 'object' || Array.isArray(v) || ![Object.prototype, null].includes(Object.getPrototypeOf(v))) return deny();
  check(Reflect.ownKeys(v).every(k => typeof k === 'string' && Object.getOwnPropertyDescriptor(v, k)?.enumerable === true && 'value' in Object.getOwnPropertyDescriptor(v, k)!));
  return v as Data;
};
const shape = (v: unknown, keys: readonly string[]): Data => {
  const d = data(v);
  check(Object.keys(d).length === keys.length && keys.every(k => Object.prototype.hasOwnProperty.call(d, k)));
  return d;
};
const list = (v: unknown): readonly unknown[] => {
  if (!Array.isArray(v) || v.length < 1 || v.length > 100) return deny();
  return v;
};
const unique = (values: readonly string[]) => check(new Set(values).size === values.length);
const professionFor = (c: Capability) => c === 'pharmacy.prescription.review' ? 'pharmacist' : 'lab_signatory';
const capabilityFor = (kind: Organization['kind']) => kind === 'pharmacy' ? 'pharmacy.prescription.review' : 'lab.report.release';
const versionKeys = ['_id', 'schemaVersion', 'revision', 'createdAt', 'updatedAt'];
const version = (d: Data, now: number) => {
  check(id(d._id) && d.schemaVersion === 1 && integer(d.revision));
  check(time(d.createdAt) && time(d.updatedAt) && d.createdAt <= d.updatedAt && d.updatedAt <= now);
};
const interval = (d: Data, now: number) => check(time(d.validFrom) && time(d.expiresAt) && d.validFrom <= now && now < d.expiresAt);
const branches = (v: unknown): readonly Branch[] => {
  const entries = list(v).map(raw => {
    const d = shape(raw, ['branchId', 'state', 'revision']);
    check(id(d.branchId) && state(d.state) && integer(d.revision));
    return d as unknown as Branch;
  });
  unique(entries.map(x => x.branchId));
  return entries;
};
const grants = (v: unknown, org: Organization, includeDecision: boolean): readonly Data[] => {
  const entries = list(v).map(raw => {
    const d = shape(raw, includeDecision ? ['branchId', 'capability', 'grantDecisionId'] : ['branchId', 'capability']);
    check(id(d.branchId) && capability(d.capability) && d.capability === capabilityFor(org.kind));
    check(org.branches.some(b => b.branchId === d.branchId));
    if (includeDecision) check(id(d.grantDecisionId));
    return d;
  });
  unique(entries.map(x => `${x.branchId}:${x.capability}`));
  return entries;
};
const evidence = (v: unknown): readonly EvidenceReference[] => {
  const entries = list(v).map(raw => {
    const d = shape(raw, ['evidenceVersionId', 'evidenceSha256']);
    check(id(d.evidenceVersionId) && digest(d.evidenceSha256));
    return d as unknown as EvidenceReference;
  });
  unique(entries.map(x => x.evidenceVersionId));
  return entries;
};
const compare = (a: string, b: string) => a < b ? -1 : a > b ? 1 : 0;
const sortedBranches = (v: readonly Branch[]) => [...v].sort((a, b) => compare(a.branchId, b.branchId)).map(x => [x.branchId, x.state, x.revision]);
const sortedGrants = (v: readonly Readonly<{ branchId: string; capability: Capability; grantDecisionId?: string }>[]) => [...v]
  .sort((a, b) => compare(`${a.branchId}:${a.capability}`, `${b.branchId}:${b.capability}`))
  .map(x => x.grantDecisionId === undefined ? [x.branchId, x.capability] : [x.branchId, x.capability, x.grantDecisionId]);
const sha256 = (text: string) => createHash('sha256').update(text, 'utf8').digest('hex');

export function validateContext(principal: unknown, request: unknown): { person: AuthenticatedPerson; request: AuthorityRequest } {
  try {
    const p = shape(principal, ['actorId', 'userType', 'purpose']);
    const r = shape(request, ['organizationId', 'branchId', 'capability']);
    check(id(p.actorId) && p.userType === 'user' && p.purpose === 'staff');
    check(id(r.organizationId) && id(r.branchId) && capability(r.capability));
    return {
      person: Object.freeze({ actorId: p.actorId as string, userType: 'user', purpose: 'staff' }),
      request: Object.freeze({ organizationId: r.organizationId as string, branchId: r.branchId as string, capability: r.capability as Capability }),
    };
  } catch (error) {
    if (error instanceof AuthorityError) throw new AuthorityError('INVALID_CONTEXT');
    throw error;
  }
}
export function validateTime(now: number): void { check(time(now)); }
export function validateReadiness(value: unknown): string {
  try {
    const r = shape(value, ['ready', 'authorityGeneration', 'indexesVerified', 'provenanceVerified', 'snapshotTransactionsVerified']);
    check(r.ready === true && digest(r.authorityGeneration) && r.indexesVerified === true && r.provenanceVerified === true && r.snapshotTransactionsVerified === true);
    return r.authorityGeneration as string;
  } catch (error) {
    if (error instanceof AuthorityError) throw new AuthorityError('AUTHORITY_NOT_READY');
    throw error;
  }
}
export function validateLookup(value: AuthorityLookup, now: number): void {
  shape(value, ['actorId', 'organizationId', 'branchId', 'capability', 'authorityGeneration']);
  check(id(value.actorId) && id(value.organizationId) && id(value.branchId) && capability(value.capability) && digest(value.authorityGeneration));
  validateTime(now);
}
export function validateUser(value: unknown, lookup: AuthorityLookup): void {
  const u = shape(value, ['_id', 'userType', 'isActive']);
  check(u._id === lookup.actorId && u.userType === 'user' && u.isActive === true);
}
export function validateOrganization(value: unknown, lookup: AuthorityLookup, now: number): Organization {
  const d = shape(value, [...versionKeys, 'kind', 'sourceBusinessId', 'state', 'sourceFingerprint', 'mappingDecisionId', 'branches']);
  version(d, now);
  check(d._id === lookup.organizationId && (d.kind === 'pharmacy' || d.kind === 'lab') && id(d.sourceBusinessId));
  check(d.state === 'active' && digest(d.sourceFingerprint) && id(d.mappingDecisionId));
  const bs = branches(d.branches);
  check(bs.filter(b => b.branchId === lookup.branchId && b.state === 'active').length === 1);
  check(lookup.capability === capabilityFor(d.kind as Organization['kind']));
  return d as unknown as Organization;
}
export function pharmacyFingerprint(value: unknown): string {
  const p = shape(value, ['_id', 'isActive', 'isVerified', 'drugLicenseNumber', 'drugLicenseDocumentUrl']);
  check(id(p._id) && p.isActive === true && p.isVerified === true);
  check(typeof p.drugLicenseNumber === 'string' && p.drugLicenseNumber.length > 0 && p.drugLicenseNumber.length <= 512);
  check(typeof p.drugLicenseDocumentUrl === 'string' && p.drugLicenseDocumentUrl.length > 0 && p.drugLicenseDocumentUrl.length <= 2048);
  return sha256(JSON.stringify(['business-source', 1, 'pharmacy', ['sourceBusinessId', p._id], ['drugLicenseNumber', p.drugLicenseNumber], ['drugLicenseDocumentUrl', p.drugLicenseDocumentUrl]]));
}

// Ordered schema-versioned arrays, not object insertion order. Metadata and evidence are bound too.
export function serializeDecision(decision: AuthorityDecision): string {
  const common: unknown[] = ['business-authority-decision', 1, decision.decisionKind,
    ['_id', decision._id], ['organizationId', decision.organizationId], ['operationId', decision.operationId],
    ['decidingActorId', decision.decidingActorId], ['decidedAt', decision.decidedAt], ['authorityGeneration', decision.authorityGeneration],
    ['evidence', [...decision.evidence].sort((a, b) => compare(a.evidenceVersionId, b.evidenceVersionId)).map(e => [e.evidenceVersionId, e.evidenceSha256])]];
  if (decision.decisionKind === 'business_mapped') {
    const p = decision.payload;
    common.push(['payload', ['organizationId', p.organizationId], ['organizationRevision', p.organizationRevision], ['kind', p.kind], ['sourceBusinessId', p.sourceBusinessId], ['sourceFingerprint', p.sourceFingerprint], ['branches', sortedBranches(p.branches)]]);
  } else if (decision.decisionKind === 'membership_granted') {
    const p = decision.payload;
    common.push(['subjectActorId', decision.subjectActorId], ['payload', ['organizationId', p.organizationId], ['actorId', p.actorId], ['membershipId', p.membershipId], ['membershipRevision', p.membershipRevision], ['validFrom', p.validFrom], ['expiresAt', p.expiresAt], ['grants', sortedGrants(p.grants)], ['branchId', p.branchId], ['capability', p.capability]]);
  } else {
    const p = decision.payload;
    common.push(['subjectActorId', decision.subjectActorId], ['payload', ['organizationId', p.organizationId], ['actorId', p.actorId], ['eligibilityId', p.eligibilityId], ['eligibilityRevision', p.eligibilityRevision], ['profession', p.profession], ['validFrom', p.validFrom], ['expiresAt', p.expiresAt], ['evidenceVersionId', p.evidenceVersionId], ['evidenceSha256', p.evidenceSha256], ['grants', sortedGrants(p.grants)]]);
  }
  return JSON.stringify(common);
}
export function decisionDigest(decision: AuthorityDecision): string { return sha256(serializeDecision(decision)); }
const one = <T>(v: readonly unknown[]): T => { check(Array.isArray(v) && v.length === 1); return v[0] as T; };
export const validateMembership = (v: unknown, lookup: AuthorityLookup, org: Organization, now: number): Membership => {
  const d = shape(v, [...versionKeys, 'organizationId', 'actorId', 'state', 'validFrom', 'expiresAt', 'grants']);
  version(d, now); interval(d, now);
  check(d.organizationId === lookup.organizationId && d.actorId === lookup.actorId && d.state === 'active');
  grants(d.grants, org, true);
  return d as unknown as Membership;
};
export const validateEligibility = (v: unknown, lookup: AuthorityLookup, now: number): Eligibility => {
  const d = shape(v, [...versionKeys, 'organizationId', 'actorId', 'profession', 'state', 'validFrom', 'expiresAt', 'verificationDecisionId', 'evidenceVersionId', 'evidenceSha256']);
  version(d, now); interval(d, now);
  check(d.organizationId === lookup.organizationId && d.actorId === lookup.actorId && d.state === 'verified' && d.profession === professionFor(lookup.capability));
  check(id(d.verificationDecisionId) && id(d.evidenceVersionId) && digest(d.evidenceSha256));
  return d as unknown as Eligibility;
};
const currentDecision = (v: unknown, kind: AuthorityDecision['decisionKind'], lookup: AuthorityLookup, org: Organization, now: number): AuthorityDecision => {
  const keys = ['_id', 'schemaVersion', 'organizationId', 'operationId', 'decisionKind', 'decidingActorId', 'decidedAt', 'authorityGeneration', 'payloadSha256', 'payload', 'evidence', 'createdAt', 'updatedAt'];
  if (kind !== 'business_mapped') keys.push('subjectActorId');
  const d = shape(v, keys);
  check(id(d._id) && d.schemaVersion === 1 && d.organizationId === lookup.organizationId && id(d.operationId) && d.decisionKind === kind && id(d.decidingActorId));
  check(time(d.decidedAt) && d.decidedAt <= now && time(d.createdAt) && time(d.updatedAt) && d.createdAt <= d.updatedAt && d.updatedAt <= now);
  check(d.authorityGeneration === lookup.authorityGeneration && digest(d.payloadSha256));
  evidence(d.evidence);
  if (kind !== 'business_mapped') check(d.subjectActorId === lookup.actorId && d.decidingActorId !== d.subjectActorId);
  if (kind === 'business_mapped') {
    const p = shape(d.payload, ['organizationId', 'organizationRevision', 'kind', 'sourceBusinessId', 'sourceFingerprint', 'branches']);
    check(id(p.organizationId) && integer(p.organizationRevision) && (p.kind === 'pharmacy' || p.kind === 'lab') && id(p.sourceBusinessId) && digest(p.sourceFingerprint));
    branches(p.branches);
  } else if (kind === 'membership_granted') {
    const p = shape(d.payload, ['organizationId', 'actorId', 'membershipId', 'membershipRevision', 'validFrom', 'expiresAt', 'grants', 'branchId', 'capability']);
    check(id(p.organizationId) && id(p.actorId) && id(p.membershipId) && integer(p.membershipRevision));
    interval(p, now); grants(p.grants, org, true);
    check(id(p.branchId) && capability(p.capability));
  } else {
    const p = shape(d.payload, ['organizationId', 'actorId', 'eligibilityId', 'eligibilityRevision', 'profession', 'validFrom', 'expiresAt', 'evidenceVersionId', 'evidenceSha256', 'grants']);
    check(id(p.organizationId) && id(p.actorId) && id(p.eligibilityId) && integer(p.eligibilityRevision) && p.profession === professionFor(lookup.capability));
    interval(p, now); grants(p.grants, org, false);
    check(id(p.evidenceVersionId) && digest(p.evidenceSha256));
  }
  const decision = d as unknown as AuthorityDecision;
  check(decisionDigest(decision) === decision.payloadSha256);
  return decision;
};

export function evaluateAuthority(lookup: AuthorityLookup, facts: AuthorityFacts, now: number): BusinessScope {
  validateLookup(lookup, now);
  shape(facts, ['user', 'organization', 'pharmacy', 'memberships', 'eligibility', 'mappingDecisions', 'grantDecisions', 'verificationDecisions']);
  validateUser(facts.user, lookup);
  const org = validateOrganization(facts.organization, lookup, now);
  if (org.kind !== 'pharmacy') throw new AuthorityError('AUTHORITY_MAPPING_UNAVAILABLE');
  const pharmacy = data(facts.pharmacy);
  check(pharmacy._id === org.sourceBusinessId && pharmacyFingerprint(pharmacy) === org.sourceFingerprint);
  const member = validateMembership(one(facts.memberships), lookup, org, now);
  const eligible = validateEligibility(one(facts.eligibility), lookup, now);
  const grant = one<StaffGrant>(member.grants.filter(g => g.branchId === lookup.branchId && g.capability === lookup.capability));
  const mapping = currentDecision(one(facts.mappingDecisions), 'business_mapped', lookup, org, now);
  const granted = currentDecision(one(facts.grantDecisions), 'membership_granted', lookup, org, now);
  const verified = currentDecision(one(facts.verificationDecisions), 'professional_verified', lookup, org, now);
  unique([mapping._id, granted._id, verified._id]);
  unique([mapping.operationId, granted.operationId, verified.operationId]);
  check(mapping._id === org.mappingDecisionId && granted._id === grant.grantDecisionId && verified._id === eligible.verificationDecisionId);
  const mp = mapping.payload as MappingPayload;
  check(mp.organizationId === org._id && mp.organizationRevision === org.revision && mp.kind === org.kind && mp.sourceBusinessId === org.sourceBusinessId && mp.sourceFingerprint === org.sourceFingerprint);
  check(JSON.stringify(sortedBranches(mp.branches)) === JSON.stringify(sortedBranches(org.branches)));
  const gp = granted.payload as GrantPayload;
  check(gp.organizationId === org._id && gp.actorId === lookup.actorId && gp.membershipId === member._id && gp.membershipRevision === member.revision && gp.validFrom === member.validFrom && gp.expiresAt === member.expiresAt && gp.branchId === lookup.branchId && gp.capability === lookup.capability);
  check(JSON.stringify(sortedGrants(gp.grants)) === JSON.stringify(sortedGrants(member.grants)));
  const vp = verified.payload as VerificationPayload;
  check(vp.organizationId === org._id && vp.actorId === lookup.actorId && vp.eligibilityId === eligible._id && vp.eligibilityRevision === eligible.revision && vp.profession === eligible.profession && vp.validFrom === eligible.validFrom && vp.expiresAt === eligible.expiresAt && vp.evidenceVersionId === eligible.evidenceVersionId && vp.evidenceSha256 === eligible.evidenceSha256);
  check(vp.grants.filter(g => g.branchId === lookup.branchId && g.capability === lookup.capability).length === 1);
  check(verified.evidence.some(e => e.evidenceVersionId === eligible.evidenceVersionId && e.evidenceSha256 === eligible.evidenceSha256));
  return {
    ...lookup, purpose: 'staff', kind: 'pharmacy', sourceBusinessId: org.sourceBusinessId,
    organizationRevision: org.revision, branchRevision: org.branches.find(b => b.branchId === lookup.branchId)!.revision,
    membershipId: member._id, membershipRevision: member.revision, eligibilityId: eligible._id, eligibilityRevision: eligible.revision,
    mappingDecisionId: mapping._id, grantDecisionId: granted._id, verificationDecisionId: verified._id,
    evidenceVersionId: eligible.evidenceVersionId, evidenceSha256: eligible.evidenceSha256,
    checkedAt: now, expiresAt: Math.min(member.expiresAt, eligible.expiresAt),
  };
}

import { AuthorityError, AuthorityReadPort, BusinessScope } from '../types';
import { evaluateAuthority, validateContext, validateReadiness, validateTime } from '../rules';

const issuedScopes = new WeakSet<object>();
export function isBusinessScope(value: unknown): value is BusinessScope {
  return !!value && typeof value === 'object' && issuedScopes.has(value);
}

// This constructor is internal composition. A caller-shaped object is never a grant.
export class BusinessStaffAuthorityService {
  constructor(private readonly port: AuthorityReadPort, private readonly clock: () => number) {}

  async resolve(principal: unknown, request: unknown, transaction: unknown): Promise<BusinessScope> {
    const context = validateContext(principal, request);
    if (!transaction || typeof transaction !== 'object') throw new AuthorityError('INVALID_TRANSACTION');
    const now = this.clock();
    validateTime(now);
    const authorityGeneration = validateReadiness(await this.port.readiness());
    const lookup = Object.freeze({ ...context.request, actorId: context.person.actorId, authorityGeneration });
    const facts = await this.port.loadFacts(lookup, transaction, now);
    const scope = Object.freeze(evaluateAuthority(lookup, facts, now));
    // Scope fields are all immutable scalars: freezing this object is a deep freeze.
    issuedScopes.add(scope);
    return scope;
  }
}

export type BusinessKind = 'pharmacy' | 'lab';
export type Capability = 'pharmacy.prescription.review' | 'lab.report.release';
export type Profession = 'pharmacist' | 'lab_signatory';
export type AuthorityState = 'active' | 'suspended' | 'revoked';
export type DecisionKind = 'business_mapped' | 'membership_granted' | 'professional_verified';
export type DenialCategory = 'INVALID_CONTEXT' | 'AUTHORITY_DENIED' | 'AUTHORITY_NOT_READY' | 'AUTHORITY_MAPPING_UNAVAILABLE' | 'INVALID_TRANSACTION';

export class AuthorityError extends Error {
  constructor(readonly category: DenialCategory) {
    super(category);
    this.name = 'AuthorityError';
  }
}

export interface AuthenticatedPerson {
  readonly actorId: string;
