    private pharmacyOrderSideEffectService: PharmacyOrderSideEffectService,
    private specialistRepository: SpecialistRepository,
    private slotRepository: SlotRepository,
    private userRepository: UserRepository,
    private emailService: EmailService,
    private pharmacyWalletRepository: PharmacyWalletRepository,
    private pharmacyWalletTransactionRepository: PharmacyWalletTransactionRepository,
    private medicineRepository: MedicineRepository
  ) {}

  private async runPharmacyPaymentCoreTransaction<T>(
    work: (session: ClientSession) => Promise<T>
  ): Promise<T> {
    const session = await startSession();
    try {
      let result: T | undefined;
      await session.withTransaction(async () => {
        result = await work(session);
      });

      if (result === undefined) {
        throw new AppError({
          status: 500,
          code: 'PHARMACY_PAYMENT_TRANSACTION_FAILED',
          message: 'Failed to complete pharmacy payment processing',
        });
      }

      return result;
    } finally {
      await session.endSession();
    }
  }

  private async incrementCouponUsageAfterProcessing(paymentRecord: IPaymentRecord): Promise<void> {
    if (!paymentRecord.couponCode) {
      return;
    }

    const coupon = await this.couponService.getByCode(paymentRecord.couponCode);
    await this.couponService.incrementUsage(coupon._id!);
  }

  private appendOrderNote(existingNotes: string | undefined, note: string): string {
    const normalized = existingNotes?.trim();
    if (!normalized) {
      return note;
    }

    if (normalized.includes(note)) {
      return normalized;
    }

    return `${normalized}\n${note}`;
  }

  private isPharmacyOrderPaymentWindowExpired(order: IPharmacyOrder): boolean {
    if (!order.createdAt) {
      return false;
    }

    const createdAtMs = new Date(order.createdAt).getTime();
    if (Number.isNaN(createdAtMs)) {
      return false;
    }

    return Date.now() - createdAtMs > PHARMACY_ORDER_PAYMENT_WINDOW_MS;
  }

  private async queuePharmacyOrderSubscriptionSyncSafely(
    orderId: string,
    trigger: 'payment_completed' | 'order_abandoned'
  ): Promise<void> {
    try {
      await this.pharmacyOrderSideEffectService.queueSubscriptionSync(orderId, trigger);
    } catch (error) {
      logger.error('Failed to queue pharmacy order subscription sync after payment flow', {
        orderId,
        trigger,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  private async queuePharmacyOrderNotificationSafely(
    orderId: string,
    trigger: 'payment_completed' | 'order_abandoned'
  ): Promise<void> {
    try {
      await this.pharmacyOrderSideEffectService.queueNotification(orderId, trigger);
    } catch (error) {
      logger.error('Failed to queue pharmacy order notification after payment flow', {
        orderId,
        trigger,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  private async handleTimedOutPharmacyOrderPayment(
    order: IPharmacyOrder,
    paymentRecord: IPaymentRecord
  ): Promise<{
    paymentRecord: IPaymentRecord;
    entity: unknown;
  }> {
    const batchInventoryItems = order.items
      .filter((item) => item.itemStatus === 'active' && item.batchAllocations?.length)
      .map((item) => ({
        medicineId: String(item.medicineId),
        batchAllocations: item.batchAllocations,
      }));
    const legacyInventoryItems = order.items
      .filter((item) => item.itemStatus === 'active' && !item.batchAllocations?.length)
      .map((item) => ({ medicineId: String(item.medicineId), quantity: item.orderedQty }));

    const refundAmount = await this.refundAbandonedPharmacyOrderToWallet(order, paymentRecord, {
      skipPaymentStateUpdate: true,
    });

    const { updatedOrder, updatedPayment } = await this.runPharmacyPaymentCoreTransaction(
      async (session) => {
        const inventoryWasAlreadyReleased = ['abandoned', 'cancelled', 'rejected'].includes(order.status);
        const nextOrder =
          inventoryWasAlreadyReleased
            ? ((await this.pharmacyOrderRepository.findById(String(order._id), session)) as IPharmacyOrder | null) ||
              order
            : ((await this.pharmacyOrderRepository.update(
                { _id: order._id },
                {
                  status: 'abandoned',
                  paymentTransactionId: paymentRecord._id!,
                  notes: this.appendOrderNote(order.notes, PHARMACY_ORDER_PAYMENT_TIMEOUT_NOTE),
                },
                { new: true, session }
              )) as IPharmacyOrder | null);

        if (!nextOrder) {
          throw new AppError({
            status: 500,
            code: 'PHARMACY_ORDER_UPDATE_FAILED',
            message: 'Failed to abandon pharmacy order after payment timeout',
          });
        }

        if (!inventoryWasAlreadyReleased && batchInventoryItems.length) {
          await this.inventoryService.releaseOrderStockBulk(
            String(nextOrder.pharmacyId),
            batchInventoryItems,
            session
          );
        }
        if (!inventoryWasAlreadyReleased && legacyInventoryItems.length) {
          await this.inventoryService.returnStockBulk(
            String(nextOrder.pharmacyId),
            legacyInventoryItems,
            session
          );
        }

        const orderAfterRefund =
          ((await this.pharmacyOrderRepository.update(
            { _id: nextOrder._id },
            {
              paymentStatus: refundAmount > 0 ? 'refunded' : nextOrder.paymentStatus,
              paymentTransactionId: paymentRecord._id!,
              notes: this.appendOrderNote(nextOrder.notes, PHARMACY_ORDER_LATE_REFUND_NOTE),
            },
            { new: true, session }
          )) as IPharmacyOrder | null) || nextOrder;

        const paymentAfterRefund =
          ((await this.paymentRepository.update(
            { _id: paymentRecord._id! },
            { status: 'refunded', isProcessed: true },
            { new: true, session }
          )) as IPaymentRecord | null) || paymentRecord;

        return {
          updatedOrder: orderAfterRefund,
          updatedPayment: paymentAfterRefund,
        };
      }
    );

    await this.queuePharmacyOrderSubscriptionSyncSafely(String(updatedOrder._id), 'order_abandoned');
    if (updatedOrder.customerId) {
      await this.queuePharmacyOrderNotificationSafely(String(updatedOrder._id), 'order_abandoned');
    }

    return {
      paymentRecord: updatedPayment,
      entity: updatedOrder,
    };
  }

  private async sendPaidBookingEmailNotification(booking: IBooking): Promise<void> {
    try {
      const user = await this.userRepository.findById(booking.userId);
      if (!user?.email) {
        return;
      }

      const content = buildPaidBookingEmailContent({
        bookingId: booking._id,
        bookingType: booking.bookingType,
        bookingDate: booking.bookingDate,
        bookingTime: booking.bookingTime,
        userName: user.name,
        consultationMode: booking.consultationMode,
        serviceMode: booking.serviceMode,
        meetJoinUrl: booking.virtualMeeting?.joinUrl,
      });

      await this.emailService.sendEmail({
        to: [user.email],
        subject: content.subject,
        textBody: content.textBody,
        htmlBody: content.htmlBody,
      });
    } catch (error) {
      logger.error('Failed to send paid booking email notification', {
        bookingId: booking._id,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  private async sendExternalBookingEmailNotification(
    booking: IExternalBooking,
    template: ExternalBookingEmailTemplate
  ): Promise<void> {
    try {
      const recipients = new Set<string>();
      if (booking.patientEmail?.trim()) {
        recipients.add(booking.patientEmail.trim());
      }

      const user = await this.userRepository.findById(booking.userId);
      if (user?.email?.trim()) {
        recipients.add(user.email.trim());
      }

      if (!recipients.size) {
        return;
      }

      const content = buildExternalBookingEmailContent({
        booking,
        template,
        userName: booking.patientName || user?.name,
      });

      await this.emailService.sendEmail({
        to: Array.from(recipients),
        subject: content.subject,
        textBody: content.textBody,
        htmlBody: content.htmlBody,
      });
    } catch (error) {
      logger.error('Failed to send external booking lifecycle email', {
        bookingId: booking._id,
        template,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  private buildLifecyclePatch(
    current: IBooking['lifecycle'],
    updates: Parameters<typeof buildBookingLifecyclePatch>[1]
  ) {
    return buildBookingLifecyclePatch(current, updates);
  }

  private getRazorpayCredentials(): { keyId: string; keySecret: string } {
    if (!CONFIG.RAZORPAY_KEY_ID || !CONFIG.RAZORPAY_KEY_SECRET) {
      throw new AppError({
        status: 500,
        code: 'RAZORPAY_NOT_CONFIGURED',
        message: 'Razorpay credentials are not configured',
      });
    }

    return {
      keyId: CONFIG.RAZORPAY_KEY_ID,
      keySecret: CONFIG.RAZORPAY_KEY_SECRET,
    };
  }

  private getRazorpayClient(): Razorpay {
    if (this.razorpayClient) {
      return this.razorpayClient;
    }

    const { keyId, keySecret } = this.getRazorpayCredentials();
    this.razorpayClient = new Razorpay({
      key_id: keyId,
      key_secret: keySecret,
    });

    return this.razorpayClient;
  }

  private buildRazorpayReceipt(data: CreatePaymentOrderRequest): string {
    const contextCode =
      data.context === 'wallet_recharge'
        ? 'wr'
        : data.context === 'external_booking'
          ? 'eb'
          : data.context === 'pharmacy_order'
            ? 'po'
          : 'bk';
    const contextId = String(data.contextId || '');
    const userId = String(data.userId || '');
    const contextIdSuffix =
      contextId.replace(/[^a-zA-Z0-9]/g, '').slice(-8) || 'ctx';
    const userIdSuffix =
      userId.replace(/[^a-zA-Z0-9]/g, '').slice(-6) || 'usr';
    const timeCode = Date.now().toString(36);
    const rawReceipt = `ewa_${contextCode}_${contextIdSuffix}_${userIdSuffix}_${timeCode}`;

    return rawReceipt.length <= 40 ? rawReceipt : rawReceipt.slice(0, 40);
  }

  private getPaymentPayerUserId(data: { payerUserId?: string; userId: string }): string {
    return data.payerUserId || data.userId;
  }

  private async assertNewPharmacyPaymentAllowed(
    data: Pick<CreatePaymentOrderRequest, 'context' | 'contextId'>
  ): Promise<void> {
    if (data.context !== 'pharmacy_order') return;
    const order = typeof data.contextId === 'string' && /^[0-9a-fA-F]{24}$/.test(data.contextId)
      ? await this.pharmacyOrderRepository.findById(data.contextId)
      : null;
    await assertPrescriptionCommerceAvailable({
      kind: 'stored_order',
      order,
      expectedOrderId: data.contextId,
      readMedicines: ids => this.medicineRepository.findAll(
        { _id: { $in: ids } },
        { select: '_id prescriptionRequired isActive archivedAt' }
      ),
    });
  }

  async createOrder(data: CreatePaymentOrderRequest): Promise<{
    paymentRecord: IPaymentRecord;
    razorpayOrder: {
      id: string;
      amount: number;
      currency: string;
      status: string;
    };
    razorpayKeyId: string;
  }> {
    if (data.finalAmount < 0) {
      throw new AppError({
        status: 400,
        code: 'INVALID_PAYMENT_AMOUNT',
        message: 'Final payment amount cannot be negative',
      });
    }

    const currency = (data.currency || 'INR').toUpperCase();
    const amountInPaise = Math.round(data.finalAmount * 100);

    if (amountInPaise <= 0) {
      throw new AppError({
        status: 400,
        code: 'INVALID_PAYMENT_AMOUNT',
        message: 'Payment amount must be greater than zero',
      });
    }

    await this.assertNewPharmacyPaymentAllowed(data);

    const { keyId } = this.getRazorpayCredentials();
    const razorpayClient = this.getRazorpayClient();

    const orderPayload = {
      amount: amountInPaise,
      currency,
      receipt: this.buildRazorpayReceipt(data),
      notes: {
        context: data.context,
        contextId: data.contextId.toString(),
        userId: data.userId,
      },
    };

    let razorpayOrder: RazorpayOrderResponse;
    try {
      const order = await razorpayClient.orders.create(orderPayload);
      razorpayOrder = {
        id: order.id,
        amount: Number(order.amount),
        currency: order.currency,
        status: order.status,
      };
    } catch (error: any) {
      throw new AppError({
        status: 502,
        code: 'RAZORPAY_ORDER_CREATION_FAILED',
        message:
          error?.error?.description ||
          error?.description ||
          'Failed to create Razorpay order',
      });
    }

    const paymentRecord = await this.paymentRepository.save({
      userId: data.userId,
      payerUserId: this.getPaymentPayerUserId(data),
      payerPharmacyId: data.payerPharmacyId,
      context: data.context,
      contextId: data.contextId,
      baseAmount: data.baseAmount,
      discountAmount: data.discountAmount || 0,
      finalAmount: data.finalAmount,
      baseAmountPaise: Math.round(data.baseAmount * 100),
      discountAmountPaise: Math.round((data.discountAmount || 0) * 100),
      finalAmountPaise: amountInPaise,
      currency,
      paymentGateway: 'razorpay',
      couponCode: data.couponCode,
      razorpayOrderId: razorpayOrder.id,
      status: 'created',
      isProcessed: false,
      notes: data.notes,
    });

    return {
      paymentRecord,
      razorpayOrder: {
        id: razorpayOrder.id,
        amount: razorpayOrder.amount,
        currency: razorpayOrder.currency,
        status: razorpayOrder.status,
      },
      razorpayKeyId: keyId,
    };
  }

  async createDirectPaidTransaction(
    data: CreateDirectPaidTransactionRequest
  ): Promise<IPaymentRecord> {
    await this.assertNewPharmacyPaymentAllowed(data);
    const currency = (data.currency || 'INR').toUpperCase();
    const baseAmountPaise = Math.round(data.baseAmount * 100);
    const discountAmountPaise = Math.round((data.discountAmount || 0) * 100);
    const finalAmountPaise = Math.round(data.finalAmount * 100);

    return this.paymentRepository.save({
      userId: data.userId,
      payerUserId: this.getPaymentPayerUserId(data),
      payerPharmacyId: data.payerPharmacyId,
      context: data.context,
      contextId: data.contextId,
      baseAmount: data.baseAmount,
      discountAmount: data.discountAmount || 0,
      finalAmount: data.finalAmount,
      baseAmountPaise,
      discountAmountPaise,
      finalAmountPaise,
      currency,
      paymentGateway: 'internal',
      couponCode: data.couponCode,
      status: 'paid',
      isProcessed: data.isProcessed ?? true,
      paidAt: new Date(),
      notes: data.notes,
    });
  }

  private async getPaymentRecordForVerification(
    data: VerifyPaymentRequest
  ): Promise<IPaymentRecord> {
    const paymentRecord = await this.paymentRepository.findById(
      data.paymentTransactionId
    );

    if (!paymentRecord) {
      throw new AppError({
        status: 404,
        code: 'PAYMENT_RECORD_NOT_FOUND',
        message: 'Payment record not found',
      });
    }

    const belongsToRequester =
      (paymentRecord.payerUserId || paymentRecord.userId) === data.userId;
    let pharmacyCanVerify = false;

    if (
      !belongsToRequester &&
      data.requesterUserType === 'pharmacy' &&
      data.requesterPharmacyId &&
      (paymentRecord.context === 'booking' || paymentRecord.context === 'pharmacy_order')
    ) {
      if (paymentRecord.context === 'booking') {
        const booking = await this.bookingRepository.findById(paymentRecord.contextId);
        pharmacyCanVerify =
          !!booking &&
          String(booking.pharmacyId) === String(data.requesterPharmacyId);
      } else {
        const order = await this.pharmacyOrderRepository.findById(paymentRecord.contextId);
        pharmacyCanVerify =
          !!order &&
          String(order.pharmacyId) === String(data.requesterPharmacyId);
      }
    }

    if (!belongsToRequester && !pharmacyCanVerify) {
      throw new AppError({
        status: 404,
        code: 'PAYMENT_RECORD_NOT_FOUND',
        message: 'Payment record not found',
      });
    }

    if (paymentRecord.razorpayOrderId !== data.razorpayOrderId) {
      throw new AppError({
        status: 400,
        code: 'PAYMENT_ORDER_MISMATCH',
        message: 'Razorpay order ID does not match',
      });
    }

    return paymentRecord;
  }

  private handleExistingRecordStatus(paymentRecord: IPaymentRecord): void {
    if (paymentRecord.status === 'paid') {
      return;
    }

    if (paymentRecord.status === 'failed') {
      throw new AppError({
        status: 400,
        code: 'PAYMENT_FAILED',
        message: 'Payment is already marked as failed',
      });
    }

    if (paymentRecord.status === 'refunded') {
      throw new AppError({
        status: 400,
        code: 'PAYMENT_REFUNDED',
        message: 'Payment is already marked as refunded',
      });
    }
  }

  private async validateSignature(
    data: VerifyPaymentRequest,
    paymentRecord: IPaymentRecord
  ): Promise<void> {
    const { keySecret } = this.getRazorpayCredentials();

    const generatedSignature = crypto
      .createHmac('sha256', keySecret)
      .update(`${data.razorpayOrderId}|${data.razorpayPaymentId}`)
      .digest('hex');

    if (generatedSignature !== data.razorpaySignature) {
      await this.paymentRepository.update(
        { _id: paymentRecord._id },
        {
          status: 'failed',
          razorpayPaymentId: data.razorpayPaymentId,
          razorpaySignature: data.razorpaySignature,
        }
      );

      throw new AppError({
        status: 400,
        code: 'PAYMENT_SIGNATURE_INVALID',
        message: 'Invalid Razorpay payment signature',
      });
    }
  }

  private async fetchRazorpayPayment(
    razorpayPaymentId: string
  ): Promise<RazorpayPaymentDetails> {
    const razorpayClient = this.getRazorpayClient();

    try {
      const payment = await razorpayClient.payments.fetch(razorpayPaymentId);
      return {
        id: payment.id,
        order_id: payment.order_id,
        amount: Number(payment.amount),
        currency: payment.currency,
        status: payment.status,
      };
    } catch (error: any) {
      throw new AppError({
        status: 502,
        code: 'RAZORPAY_PAYMENT_FETCH_FAILED',
        message:
          error?.error?.description ||
          error?.description ||
          'Failed to verify payment with Razorpay',
      });
    }
  }

  private validateRazorpayPaymentForRecord(
    paymentRecord: IPaymentRecord,
    data: VerifyPaymentRequest,
    razorpayPayment: RazorpayPaymentDetails
  ): void {
    if (razorpayPayment.order_id !== data.razorpayOrderId) {
      throw new AppError({
        status: 400,
        code: 'PAYMENT_ORDER_MISMATCH',
        message: 'Razorpay payment does not belong to the provided order',
      });
    }

    const expectedAmountInPaise =
      paymentRecord.finalAmountPaise ?? Math.round(paymentRecord.finalAmount * 100);
    if (razorpayPayment.amount !== expectedAmountInPaise) {
      throw new AppError({
        status: 400,
        code: 'PAYMENT_AMOUNT_MISMATCH',
        message: 'Razorpay payment amount does not match expected amount',
      });
    }

    if (
      razorpayPayment.currency.toUpperCase() !==
      paymentRecord.currency.toUpperCase()
    ) {
      throw new AppError({
        status: 400,
        code: 'PAYMENT_CURRENCY_MISMATCH',
        message: 'Razorpay payment currency does not match expected currency',
      });
    }
  }

  private async handleGatewayTerminalStatus(
    paymentRecord: IPaymentRecord,
    data: VerifyPaymentRequest,
    razorpayPayment: RazorpayPaymentDetails
  ): Promise<void> {
    if (razorpayPayment.status === 'failed') {
      await this.paymentRepository.update(
        { _id: paymentRecord._id },
        {
          status: 'failed',
          isProcessed: true,
          razorpayPaymentId: data.razorpayPaymentId,
          razorpaySignature: data.razorpaySignature,
        }
      );

      throw new AppError({
        status: 400,
        code: 'PAYMENT_FAILED',
        message: 'Razorpay payment failed',
      });
    }

    if (razorpayPayment.status === 'refunded') {
      await this.paymentRepository.update(
        { _id: paymentRecord._id },
        {
          status: 'refunded',
          isProcessed: true,
          razorpayPaymentId: data.razorpayPaymentId,
          razorpaySignature: data.razorpaySignature,
        }
      );

      throw new AppError({
        status: 400,
        code: 'PAYMENT_REFUNDED',
        message: 'Razorpay payment is already refunded',
      });
    }

    if (razorpayPayment.status !== 'captured') {
      throw new AppError({
        status: 400,
        code: 'PAYMENT_NOT_COMPLETED',
        message: `Razorpay payment is not completed. Current status: ${razorpayPayment.status}`,
      });
    }
  }

  private async markPaymentAsPaid(
    paymentRecord: IPaymentRecord,
    data: VerifyPaymentRequest
  ): Promise<IPaymentRecord> {
    const updated = await this.paymentRepository.update(
      { _id: paymentRecord._id },
      {
        status: 'paid',
        razorpayPaymentId: data.razorpayPaymentId,
        razorpaySignature: data.razorpaySignature,
        paidAt: new Date(),
      }
    );

    if (!updated) {
      throw new AppError({
        status: 500,
        code: 'PAYMENT_UPDATE_FAILED',
        message: 'Failed to update payment status',
      });
    }

    return updated;
  }

  async verifyAndMarkPaid(data: VerifyPaymentRequest): Promise<IPaymentRecord> {
    const paymentRecord = await this.getPaymentRecordForVerification(data);

    if (paymentRecord.status === 'paid') {
      return paymentRecord;
    }

    this.handleExistingRecordStatus(paymentRecord);
    await this.validateSignature(data, paymentRecord);

    const razorpayPayment = await this.fetchRazorpayPayment(
      data.razorpayPaymentId
    );
    this.validateRazorpayPaymentForRecord(paymentRecord, data, razorpayPayment);
    await this.handleGatewayTerminalStatus(paymentRecord, data, razorpayPayment);

    return this.markPaymentAsPaid(paymentRecord, data);
  }

  async markAsProcessed(paymentRecordId: string): Promise<void> {
    await this.paymentRepository.update(
      { _id: paymentRecordId },
      { isProcessed: true }
    );
  }

  async markAsProcessedIfNotProcessed(paymentRecordId: string): Promise<boolean> {
    const updated = await this.paymentRepository.update(
      { _id: paymentRecordId, isProcessed: false },
      { isProcessed: true }
    );
    return !!updated;
  }

  private async finalizePaymentProcessing(
    paymentRecord: IPaymentRecord
  ): Promise<IPaymentRecord> {
    const finalized = await this.markAsProcessedIfNotProcessed(paymentRecord._id!);
    if (finalized && paymentRecord.couponCode) {
      const coupon = await this.couponService.getByCode(paymentRecord.couponCode);
      await this.couponService.incrementUsage(coupon._id!);
    }

    const processedPayment = await this.paymentRepository.findById(paymentRecord._id!);
    return processedPayment || paymentRecord;
  }

  private shouldFulfillExternalBooking(
    paymentRecord: IPaymentRecord,
    module?: string
  ): boolean {
    if (paymentRecord.context === 'wallet_recharge') {
      return false;
    }
    if (paymentRecord.context === 'external_booking') {
      return true;
    }
    return module === 'external-bookings';
  }

  private async buildAlreadyProcessedResponse(
    paymentRecord: IPaymentRecord,
    module?: string
  ): Promise<{
    context: 'booking' | 'wallet_recharge' | 'external_booking' | 'pharmacy_order';
    paymentRecord: IPaymentRecord;
    entity: unknown;
  }> {
    if (this.shouldFulfillExternalBooking(paymentRecord, module)) {
      const external = await this.externalBookingRepository.findById(
        paymentRecord.contextId
      );
      return {
        context: 'external_booking',
        paymentRecord,
        entity: external || {},
      };
    }

    if (paymentRecord.context === 'booking') {
      const booking = await this.bookingRepository.findById(paymentRecord.contextId);
      return {
        context: 'booking',
        paymentRecord,
        entity: booking || {},
      };
    }

    if (paymentRecord.context === 'pharmacy_order') {
      const order = await this.pharmacyOrderRepository.findById(paymentRecord.contextId);
      return {
        context: 'pharmacy_order',
        paymentRecord,
        entity: order || {},
      };
    }

    if (this.isPharmacyWalletRecharge(paymentRecord)) {
      const wallet = await this.pharmacyWalletRepository.findByPharmacy(
        paymentRecord.payerPharmacyId!
      );
      return {
        context: 'wallet_recharge',
        paymentRecord,
        entity: wallet || {},
      };
    }

    const wallet = await this.walletRepository.findByUserId(paymentRecord.userId);
    return {
      context: 'wallet_recharge',
      paymentRecord,
      entity: wallet || {},
    };
  }

  private async processBookingPayment(
    paymentRecord: IPaymentRecord
  ): Promise<{
    paymentRecord: IPaymentRecord;
    entity: unknown;
  }> {
    const booking = await this.bookingRepository.findById(paymentRecord.contextId);

    if (!booking || booking.userId !== paymentRecord.userId) {
      throw new AppError({
        status: 404,
        code: 'BOOKING_NOT_FOUND',
        message: 'Booking not found for this payment',
      });
    }

    const updatedBooking = await this.bookingRepository.update(
      { _id: booking._id },
      {
        paymentStatus: 'paid',
        paymentTransactionId: paymentRecord._id!,
        status: booking.status === 'pending' ? 'confirmed' : booking.status,
        lifecycle: this.buildLifecyclePatch(booking.lifecycle, {
          paid: { amount: Number(paymentRecord.finalAmount || booking.price || 0) },
          confirmed: booking.status === 'pending' ? true : undefined,
        }),
      }
    );

    if (!updatedBooking) {
      throw new AppError({
        status: 500,
        code: 'BOOKING_UPDATE_FAILED',
        message: 'Failed to update booking payment status',
      });
    }

    let bookingForResponse = updatedBooking;
    if (updatedBooking.status === 'confirmed') {
      await this.bookingReminderScheduler.scheduleBookingReminders(updatedBooking);
      bookingForResponse = await syncBookingMeet({
        booking: updatedBooking,
        bookingRepository: this.bookingRepository,
        userRepository: this.userRepository,
        specialistRepository: this.specialistRepository,
        slotRepository: this.slotRepository,
      });
    }

    await this.sendPaidBookingEmailNotification(bookingForResponse as IBooking);

    const finalizedPayment = await this.finalizePaymentProcessing(paymentRecord);
    return {
      paymentRecord: finalizedPayment,
      entity: bookingForResponse,
    };
  }

  private async processPharmacyOrderPayment(
    paymentRecord: IPaymentRecord
  ): Promise<{
    paymentRecord: IPaymentRecord;
    entity: unknown;
  }> {
    let order = await this.pharmacyOrderRepository.findById(paymentRecord.contextId);

    if (!order) {
      throw new AppError({
        status: 404,
        code: 'PHARMACY_ORDER_NOT_FOUND',
        message: 'Pharmacy order not found for this payment',
      });
    }

    if (['abandoned', 'cancelled', 'rejected'].includes(order.status)) {
      return this.handleTimedOutPharmacyOrderPayment(order as IPharmacyOrder, paymentRecord);
    }

    if (
      order.paymentMode === 'online_payment' &&
      order.paymentStatus === 'pending' &&
      this.isPharmacyOrderPaymentWindowExpired(order as IPharmacyOrder)
    ) {
      return this.handleTimedOutPharmacyOrderPayment(order as IPharmacyOrder, paymentRecord);
    }

    if (order.paymentMode === 'online_payment' && order.paymentStatus === 'pending') {
      const claimedOrder = await this.pharmacyOrderRepository.update(
        { _id: order._id, status: 'placed', paymentStatus: 'pending' },
        {
          paymentStatus: 'authorized',
          paymentTransactionId: paymentRecord._id!,
        }
      );

      if (claimedOrder) {
        order = claimedOrder;
      } else {
        const latestOrder = await this.pharmacyOrderRepository.findById(paymentRecord.contextId);
        if (!latestOrder) {
          throw new AppError({
            status: 404,
            code: 'PHARMACY_ORDER_NOT_FOUND',
            message: 'Pharmacy order not found for this payment',
          });
        }
        order = latestOrder;
        if (['abandoned', 'cancelled', 'rejected'].includes(order.status)) {
          return this.handleTimedOutPharmacyOrderPayment(order as IPharmacyOrder, paymentRecord);
        }

        if (
          order.paymentMode === 'online_payment' &&
          order.paymentStatus === 'pending' &&
          this.isPharmacyOrderPaymentWindowExpired(order as IPharmacyOrder)
        ) {
          return this.handleTimedOutPharmacyOrderPayment(order as IPharmacyOrder, paymentRecord);
        }
      }
    }

    // Re-read after the authorization claim. A cancellation racing with the
    // gateway callback must be refunded, never revived as a paid order.
    const latestBeforePaymentCommit = await this.pharmacyOrderRepository.findById(
      paymentRecord.contextId
    );
    if (
      latestBeforePaymentCommit &&
      ['abandoned', 'cancelled', 'rejected'].includes(latestBeforePaymentCommit.status)
    ) {
      return this.handleTimedOutPharmacyOrderPayment(
        latestBeforePaymentCommit as IPharmacyOrder,
        paymentRecord
      );
    }
    if (latestBeforePaymentCommit) order = latestBeforePaymentCommit;

    const { updatedOrder, updatedPayment, paymentProcessingClaimed } =
      await this.runPharmacyPaymentCoreTransaction(async (session) => {
        const nextOrder = await this.pharmacyOrderRepository.update(
          {
            _id: order._id,
            status: { $nin: ['abandoned', 'cancelled', 'rejected', 'completed'] },
            paymentStatus: { $in: ['pending', 'authorized'] },
          },
          {
            status: order.status === 'placed' ? 'accepted' : order.status,
            paymentStatus: 'paid',
            paymentTransactionId: paymentRecord._id!,
          },
          { new: true, session }
        );

        if (!nextOrder) {
          throw new AppError({
            status: 500,
            code: 'PHARMACY_ORDER_UPDATE_FAILED',
            message: 'Failed to update pharmacy order payment status',
          });
        }

        const processedPayment = await this.paymentRepository.update(
          { _id: paymentRecord._id!, isProcessed: false },
          { isProcessed: true },
          { new: true, session }
        );

        const latestPayment =
          processedPayment ||
          ((await this.paymentRepository.findById(paymentRecord._id!, session)) as IPaymentRecord | null) ||
          paymentRecord;

        return {
          updatedOrder: nextOrder,
          updatedPayment: latestPayment,
          paymentProcessingClaimed: Boolean(processedPayment),
        };
      });

    if (!updatedOrder) {
      throw new AppError({
        status: 500,
        code: 'PHARMACY_ORDER_UPDATE_FAILED',
        message: 'Failed to update pharmacy order payment status',
      });
    }

    await this.queuePharmacyOrderSubscriptionSyncSafely(String(updatedOrder._id), 'payment_completed');
    if (updatedOrder.customerId) {
      await this.queuePharmacyOrderNotificationSafely(String(updatedOrder._id), 'payment_completed');
    }

    if (paymentProcessingClaimed) {
      await this.incrementCouponUsageAfterProcessing(updatedPayment);
    }

    return {
      paymentRecord: updatedPayment,
      entity: updatedOrder,
    };
  }

  private async processExternalBookingPayment(
    paymentRecord: IPaymentRecord
  ): Promise<{
    paymentRecord: IPaymentRecord;
    entity: unknown;
  }> {
    const updatedExternal = await this.finalizeExternalBookingPayment(
      paymentRecord,
    );

    const finalizedPayment = await this.finalizePaymentProcessing(paymentRecord);
    await this.sendExternalBookingEmailNotification(
      updatedExternal as IExternalBooking,
      'ORDER_SCHEDULED'
    );
    return {
      paymentRecord: finalizedPayment,
      entity: updatedExternal,
    };
  }

  async recoverExternalBookingPayment(
    paymentRecord: IPaymentRecord
  ): Promise<{
    paymentRecord: IPaymentRecord;
    entity: unknown;
  }> {
    logger.info('[Payment][external] recover fulfillment requested', {
      paymentTransactionId: paymentRecord._id,
      bookingId: paymentRecord.contextId,
      paymentStatus: paymentRecord.status,
      isProcessed: paymentRecord.isProcessed,
    });
    return this.processExternalBookingPayment(paymentRecord);
  }

  async finalizeExternalBookingPayment(
    paymentRecord: IPaymentRecord
  ): Promise<unknown> {
    return completeExternalBookingAfterPayment(
      paymentRecord,
      this.externalBookingRepository,
      this.labstackService,
      this.healthiansService
    );
  }

  private isRecoverableExternalFulfillmentError(error: unknown): boolean {
    const message =
      error instanceof Error ? error.message.toLowerCase() : String(error).toLowerCase();
    return message.includes('timeout') || message.includes('status code 5');
  }

  private async markExternalBookingConfirmationPending(
    paymentRecord: IPaymentRecord,
    error: unknown
  ): Promise<unknown> {
    logger.error('[Payment][external] fulfillment pending after verify', {
      paymentTransactionId: paymentRecord._id,
      bookingId: paymentRecord.contextId,
      paymentStatus: paymentRecord.status,
      isProcessed: paymentRecord.isProcessed,
      error: error instanceof Error ? error.message : String(error),
    });
    const booking = await this.externalBookingRepository.findById(paymentRecord.contextId);
    if (!booking) {
      throw error instanceof Error ? error : new Error(String(error));
    }

    const priorMeta =
      booking.meta && typeof booking.meta === 'object' && !Array.isArray(booking.meta)
        ? { ...(booking.meta as Record<string, unknown>) }
        : {};

    const updated = await this.externalBookingRepository.update(
      { _id: paymentRecord.contextId },
      {
        status: 'pending',
        paymentStatus: 'paid',
        paymentTransactionId: paymentRecord._id!,
        meta: {
          ...priorMeta,
          paymentConfirmationPendingAt:
            (priorMeta.paymentConfirmationPendingAt as string | undefined) ||
            new Date().toISOString(),
          paymentConfirmationError:
            error instanceof Error ? error.message : String(error),
        },
      }
    );

    if (updated) {
      await this.sendExternalBookingEmailNotification(
        updated as IExternalBooking,
        'CREATED'
      );
    }

    return updated;
  }

  private async getOrCreateActiveWallet(userId: string) {
    let wallet = await this.walletRepository.findByUserId(userId);

    if (!wallet) {
      wallet = await this.walletRepository.save({
        userId,
        balance: 0,
        isActive: true,
      });
    }

    if (!wallet.isActive) {
      throw new AppError({
        status: 400,
        code: 'WALLET_INACTIVE',
        message: 'Wallet is not active',
      });
    }

    return wallet;
  }

  private isPharmacyWalletRecharge(paymentRecord: IPaymentRecord): boolean {
    return (
      paymentRecord.context === 'wallet_recharge' &&
      Boolean(paymentRecord.payerPharmacyId) &&
      paymentRecord.notes?.flow === 'pharmacy_wallet_recharge'
    );
  }

  private async ensurePharmacyWalletRechargeTransaction(
    paymentRecord: IPaymentRecord
  ): Promise<unknown> {
    const pharmacyId = paymentRecord.payerPharmacyId!;
    await this.pharmacyWalletRepository.upsertWallet(pharmacyId);

    try {
      return await this.runPharmacyPaymentCoreTransaction(async (session) => {
        const existingTransaction = await this.pharmacyWalletTransactionRepository.findOne(
          {
            pharmacyId,
            referenceType: 'wallet_recharge',
            referenceId: paymentRecord._id!,
            status: 'completed',
          },
          session
        );
        if (existingTransaction) {
          return this.pharmacyWalletRepository.findOne({ pharmacyId }, session);
        }

        const amountPaise =
          paymentRecord.baseAmountPaise ?? Math.round(paymentRecord.baseAmount * 100);
        const updated = await this.pharmacyWalletRepository.atomicCredit(
          pharmacyId,
          amountPaise / 100,
          session
        );
        if (!updated) {
          throw new AppError({
            status: 500,
            code: 'PHARMACY_WALLET_CREDIT_FAILED',
            message: 'Failed to credit pharmacy wallet after payment',
          });
        }

        const balanceAfterPaise = updated.balancePaise ?? Math.round(updated.balance * 100);
        const balanceBeforePaise = balanceAfterPaise - amountPaise;
        await this.pharmacyWalletTransactionRepository.save(
          {
            pharmacyId,
            walletId: String(updated._id),
            transactionType: 'credit',
            amount: amountPaise / 100,
            amountPaise,
            balanceBefore: balanceBeforePaise / 100,
            balanceAfter: balanceAfterPaise / 100,
            balanceBeforePaise,
            balanceAfterPaise,
            status: 'completed',
            referenceType: 'wallet_recharge',
            referenceId: paymentRecord._id!,
            description: 'Pharmacy wallet recharge via Razorpay',
            notes: paymentRecord.razorpayPaymentId,
            transactionDate: getTodayYyyymmdd(),
          },
          { session }
        );

        return updated;
      });
    } catch (error) {
      if (isDuplicateKeyError(error)) {
        const wallet = await this.pharmacyWalletRepository.findByPharmacy(pharmacyId);
        if (wallet) return wallet;
      }
      throw error;
    }
  }

  private async ensureWalletRechargeTransaction(paymentRecord: IPaymentRecord): Promise<unknown> {
    let wallet = await this.getOrCreateActiveWallet(paymentRecord.userId);

    const existingTransaction = await this.walletTransactionRepository.findOne({
      userId: paymentRecord.userId,
      referenceType: 'wallet_recharge',
      referenceId: paymentRecord._id!,
      status: 'completed',
    });

    if (!existingTransaction) {
      const balanceBefore = wallet.balance;
      const balanceAfter = balanceBefore + paymentRecord.baseAmount;

      await this.walletTransactionRepository.save({
        userId: paymentRecord.userId,
        walletId: wallet._id!,
        transactionType: 'credit',
        amount: paymentRecord.baseAmount,
        balanceBefore,
        balanceAfter,
        status: 'completed',
        referenceType: 'wallet_recharge',
        referenceId: paymentRecord._id!,
        description: `Wallet recharge via Razorpay${paymentRecord.couponCode ? ` (coupon: ${paymentRecord.couponCode})` : ''}`,
        notes: paymentRecord.razorpayPaymentId,
        transactionDate: getTodayYyyymmdd(),
      });

      wallet = (await this.walletRepository.update(
        { _id: wallet._id! },
        { balance: balanceAfter }
      )) || wallet;
    }

    return wallet;
  }

  private getExternalBookingMeta(
    booking: Pick<IExternalBooking, 'meta'>
  ): Record<string, unknown> {
    return booking.meta &&
      typeof booking.meta === 'object' &&
      !Array.isArray(booking.meta)
      ? { ...(booking.meta as Record<string, unknown>) }
      : {};
  }

  private getExternalAppointmentId(booking: IExternalBooking): string | undefined {
    if (booking.externalBookingId?.trim()) {
      return booking.externalBookingId.trim();
    }

    const root = this.getExternalBookingMeta(booking);
    const externalPayload =
      root.externalPayload && typeof root.externalPayload === 'object'
        ? (root.externalPayload as Record<string, unknown>)
        : undefined;
    const bookingResponse =
      externalPayload?.bookingResponse &&
      typeof externalPayload.bookingResponse === 'object'
        ? (externalPayload.bookingResponse as Record<string, unknown>)
        : undefined;
    const order =
      bookingResponse?.order && typeof bookingResponse.order === 'object'
        ? (bookingResponse.order as Record<string, unknown>)
        : undefined;
    const appointment =
      bookingResponse?.appointment &&
      typeof bookingResponse.appointment === 'object'
        ? (bookingResponse.appointment as Record<string, unknown>)
        : undefined;

    const source = order || appointment || bookingResponse || externalPayload || root;
    const candidates = ['orderId', 'appointmentId', 'lsAppointmentId', 'referenceId', 'id'];

    for (const key of candidates) {
      const value = source[key];
      if (typeof value === 'string' && value.trim()) {
        return value.trim();
      }
    }

    return undefined;
  }

  private async refundExternalBookingAmountToWallet(
    booking: IExternalBooking,
    paymentRecord: IPaymentRecord
  ): Promise<number> {
    const referenceId = String(booking._id!);

    const existingRefund = await this.walletTransactionRepository.findOne({
      userId: booking.userId,
      transactionType: 'refund',
      referenceType: 'external_booking',
      referenceId,
      status: 'completed',
    });
    if (existingRefund) {
      return Number(existingRefund.amount || 0);
    }

    const walletDeductedAmount = Number(paymentRecord.notes?.walletDeductedAmount || 0);
    const gatewayPaidAmount =
      paymentRecord.status === 'paid' ? Number(paymentRecord.finalAmount || 0) : 0;
    const refundAmount = walletDeductedAmount + gatewayPaidAmount;

    if (refundAmount > 0) {
      const wallet = await this.getOrCreateActiveWallet(booking.userId);
      const balanceBefore = wallet.balance;
      const balanceAfter = balanceBefore + refundAmount;

      await this.walletTransactionRepository.save({
        userId: booking.userId,
        walletId: wallet._id!,
        transactionType: 'refund',
        amount: refundAmount,
        balanceBefore,
        balanceAfter,
        status: 'completed',
        referenceType: 'external_booking',
        referenceId,
        description: 'Refund for external booking',
        transactionDate: getTodayYyyymmdd(),
      });

      await this.walletRepository.update({ _id: wallet._id! }, { balance: balanceAfter });
    }

    if (paymentRecord.couponCode && paymentRecord.isProcessed) {
      try {
        const coupon = await this.couponService.getByCode(paymentRecord.couponCode);
        await this.couponService.decrementUsage(coupon._id!);
      } catch (error) {
        logger.error('[Payment][external] failed to reverse coupon usage on refund', {
          bookingId: booking._id,
          paymentTransactionId: paymentRecord._id,
          couponCode: paymentRecord.couponCode,
          error: error instanceof Error ? error.message : String(error),
        });
      }
    }

    await this.paymentRepository.update(
      { _id: paymentRecord._id! },
      { status: 'refunded', isProcessed: true }
    );

    return refundAmount;
  }

  private async refundAbandonedPharmacyOrderToWallet(
    order: IPharmacyOrder,
    paymentRecord: IPaymentRecord,
    options: { skipPaymentStateUpdate?: boolean } = {}
  ): Promise<number> {
    const referenceId = String(order._id!);
    const refundUserId = paymentRecord.payerUserId || paymentRecord.userId;

    const existingRefund = await this.walletTransactionRepository.findOne({
      userId: refundUserId,
      transactionType: 'refund',
      referenceType: 'pharmacy_order',
      referenceId,
      status: 'completed',
    });
    if (existingRefund) {
      return Number(existingRefund.amount || 0);
    }

    const walletDeductedAmount = Number(paymentRecord.notes?.walletDeductedAmount || 0);
    const gatewayPaidAmount =
      paymentRecord.status === 'paid' ? Number(paymentRecord.finalAmount || 0) : 0;
    const refundAmount = walletDeductedAmount + gatewayPaidAmount;

    if (refundAmount > 0) {
      await this.getOrCreateActiveWallet(refundUserId);
      const session = await startSession();
      try {
        await session.withTransaction(async () => {
          const alreadyRefunded = await this.walletTransactionRepository.findOne(
            {
              userId: refundUserId,
              transactionType: 'refund',
              referenceType: 'pharmacy_order',
              referenceId,
              status: 'completed',
            },
            session
          );
          if (alreadyRefunded) return;

          const updatedWallet = await this.walletRepository.atomicCredit(
            refundUserId,
            refundAmount,
            session
          );
          if (!updatedWallet) {
            throw new AppError({
              status: 500,
              code: 'PHARMACY_ORDER_REFUND_FAILED',
              message: 'Refund wallet could not be credited',
            });
          }
          const balanceAfter = updatedWallet.balance;
          await this.walletTransactionRepository.save(
            {
              userId: refundUserId,
              walletId: updatedWallet._id!,
              transactionType: 'refund',
              amount: refundAmount,
              balanceBefore: balanceAfter - refundAmount,
              balanceAfter,
              status: 'completed',
              referenceType: 'pharmacy_order',
              referenceId,
              description: 'Refund for abandoned pharmacy order',
              transactionDate: getTodayYyyymmdd(),
            },
            { session }
          );
        });
      } finally {
        await session.endSession();
      }
    }

    if (paymentRecord.couponCode && paymentRecord.isProcessed) {
      try {
        const coupon = await this.couponService.getByCode(paymentRecord.couponCode);
        await this.couponService.decrementUsage(coupon._id!);
      } catch (error) {
        logger.error('[Payment][pharmacy_order] failed to reverse coupon usage on refund', {
          orderId: order._id,
          paymentTransactionId: paymentRecord._id,
          couponCode: paymentRecord.couponCode,
          error: error instanceof Error ? error.message : String(error),
        });
      }
    }

    if (!options.skipPaymentStateUpdate) {
      await this.paymentRepository.update(
        { _id: paymentRecord._id! },
        { status: 'refunded', isProcessed: true }
      );
    }

    return refundAmount;
  }

  private async handleTerminalExternalFulfillmentFailure(
    paymentRecord: IPaymentRecord,
    error: unknown
  ): Promise<{ refunded: boolean; booking?: IExternalBooking }> {
    const booking = (await this.externalBookingRepository.findById(
      paymentRecord.contextId
    )) as IExternalBooking | null;

    if (!booking) {
      return { refunded: false };
    }

    const externalAppointmentId = this.getExternalAppointmentId(booking);
    if (externalAppointmentId) {
      return { refunded: false, booking };
    }

    const priorMeta = this.getExternalBookingMeta(booking);
    const refundAmount = await this.refundExternalBookingAmountToWallet(
      booking,
      paymentRecord
    );

    const updated =
      (await this.externalBookingRepository.update(
        { _id: paymentRecord.contextId },
        {
          status: 'cancelled',
          paymentStatus: refundAmount > 0 ? 'refunded' : 'cancelled',
          paymentTransactionId: paymentRecord._id!,
          meta: {
            ...priorMeta,
            cancellationReason:
              'Booking creation failed after payment confirmation',
            cancelRequestedWhileConfirmationPending: true,
            cancelRequestedAt:
              (priorMeta.cancelRequestedAt as string | undefined) ||
              new Date().toISOString(),
            needsProviderCancelIfDiscovered: true,
            paymentFulfillmentFailedAt: new Date().toISOString(),
            paymentFulfillmentError:
              error instanceof Error ? error.message : String(error),
            ...(refundAmount > 0 ? { paymentFailureWalletRefunded: true } : {}),
          },
        }
      )) || booking;

    await this.sendExternalBookingEmailNotification(
      updated as IExternalBooking,
      'CANCELED'
    );

    return { refunded: refundAmount > 0, booking: updated as IExternalBooking };
  }

  private async processWalletRechargePayment(
    paymentRecord: IPaymentRecord
  ): Promise<{
    paymentRecord: IPaymentRecord;
    entity: unknown;
  }> {
    const wallet = this.isPharmacyWalletRecharge(paymentRecord)
      ? await this.ensurePharmacyWalletRechargeTransaction(paymentRecord)
      : await this.ensureWalletRechargeTransaction(paymentRecord);
    const finalizedPayment = await this.finalizePaymentProcessing(paymentRecord);

    return {
      paymentRecord: finalizedPayment,
      entity: wallet,
    };
  }

  async verifyPaymentAndProcess(data: VerifyPaymentRequest): Promise<{
    context: 'booking' | 'wallet_recharge' | 'external_booking' | 'pharmacy_order';
    paymentRecord: IPaymentRecord;
    entity: unknown;
  }> {
    logger.info('[Payment][verify] request received', {
      paymentTransactionId: data.paymentTransactionId,
      razorpayOrderId: data.razorpayOrderId,
      userId: data.userId,
      module: data.module,
    });
    const paymentRecord = await this.verifyAndMarkPaid(data);

    logger.info('[Payment][verify] payment verified', {
      paymentTransactionId: paymentRecord._id,
      bookingId: paymentRecord.contextId,
      context: paymentRecord.context,
      paymentStatus: paymentRecord.status,
      isProcessed: paymentRecord.isProcessed,
    });

    if (paymentRecord.isProcessed) {
      logger.info('[Payment][verify] already processed, returning existing entity', {
        paymentTransactionId: paymentRecord._id,
        bookingId: paymentRecord.contextId,
      });
      return this.buildAlreadyProcessedResponse(paymentRecord, data.module);
    }

    if (this.shouldFulfillExternalBooking(paymentRecord, data.module)) {
      try {
        logger.info('[Payment][external] fulfillment start after verify', {
          paymentTransactionId: paymentRecord._id,
          bookingId: paymentRecord.contextId,
          paymentStatus: paymentRecord.status,
          isProcessed: paymentRecord.isProcessed,
        });
        const result = await this.processExternalBookingPayment(paymentRecord);
        logger.info('[Payment][external] fulfillment success after verify', {
          paymentTransactionId: result.paymentRecord._id,
          bookingId: paymentRecord.contextId,
          paymentStatus: result.paymentRecord.status,
          isProcessed: result.paymentRecord.isProcessed,
        });
        return {
          context: 'external_booking',
          paymentRecord: result.paymentRecord,
          entity: result.entity,
        };
      } catch (error) {
        if (!this.isRecoverableExternalFulfillmentError(error)) {
          let refunded = false;
          try {
            const handled = await this.handleTerminalExternalFulfillmentFailure(
              paymentRecord,
              error
            );
            refunded = handled.refunded;
          } catch (cleanupError) {
            logger.error('[Payment][external] terminal failure cleanup failed', {
              paymentTransactionId: paymentRecord._id,
              bookingId: paymentRecord.contextId,
              cleanupError:
                cleanupError instanceof Error
                  ? cleanupError.message
                  : String(cleanupError),
            });
          }

          logger.error('[Payment][external] fulfillment failed after verify', {
            paymentTransactionId: paymentRecord._id,
            bookingId: paymentRecord.contextId,
            error: error instanceof Error ? error.message : String(error),
            refundedToWallet: refunded,
          });
          if (refunded) {
            throw new AppError({
              status: 502,
              code: 'EXTERNAL_BOOKING_FULFILLMENT_FAILED_REFUNDED',
              message: `External booking failed after payment and the amount was refunded to wallet. Original error: ${
                error instanceof Error ? error.message : String(error)
              }`,
            });
          }
          throw error;
        }

        const pendingEntity =
          await this.markExternalBookingConfirmationPending(paymentRecord, error);

        return {
          context: 'external_booking',
          paymentRecord,
          entity: pendingEntity || {},
        };
      }
    }

    if (paymentRecord.context === 'booking') {
      const result = await this.processBookingPayment(paymentRecord);

      return {
        context: 'booking',
        paymentRecord: result.paymentRecord,
        entity: result.entity,
      };
    }

    if (paymentRecord.context === 'wallet_recharge') {
      const result = await this.processWalletRechargePayment(paymentRecord);

      return {
        context: 'wallet_recharge',
        paymentRecord: result.paymentRecord,
        entity: result.entity,
      };
    }

    if (paymentRecord.context === 'pharmacy_order') {
      const result = await this.processPharmacyOrderPayment(paymentRecord);

      return {
        context: 'pharmacy_order',
        paymentRecord: result.paymentRecord,
        entity: result.entity,
      };
    }

    throw new AppError({
      status: 400,
      code: 'UNSUPPORTED_PAYMENT_CONTEXT',
      message: 'Unsupported payment context',
    });
  }
}

import 'reflect-metadata';
import { Response, NextFunction } from 'express';
import { Container } from 'typedi';
import { InventoryService } from '@/modules/pharmacyInventory/services';
import { PharmacyService } from '@/modules/pharmacies/services';
import { AuthRequest } from '@/modules/middleware/auth';
import {
  CreateInventoryItemsRequest,
  InventoryQueryParams,
  InventoryQualityHoldStatus,
  InventoryQualityWorklistQuery,
  ManualInventoryReservationRequest,
} from '@/modules/pharmacyInventory/types';
import { AppError } from '@/modules/common/types';

type InventoryResponseShape = {
  _id?: string;
  pharmacyId: string;
  medicineId: string;
  availableQty: number;
  reservedQty: number;
  freeQty: number;
  reorderThreshold?: number;
  rackLocation?: string;
  purchasePrice?: number;
  retailPrice?: number;
  wholesalePrice?: number;
  batchNumber?: string;
  expiryDate?: string;
  isActive?: boolean;
  createdAt?: Date;
  updatedAt?: Date;
  batches?: unknown[];
};

export class InventoryController {
  private inventoryService: InventoryService;
  private pharmacyService: PharmacyService;

  constructor() {
    this.inventoryService = Container.get(InventoryService);
    this.pharmacyService = Container.get(PharmacyService);
  }

  private sanitizeInventoryItem(req: AuthRequest, item: any): Partial<InventoryResponseShape> {
    if (req.user?.userType === 'admin') {
      if (req.query.includeBatches === 'true') return item;
      const { batches: _batches, ...withoutBatches } = item;
      return withoutBatches;
    }

    if (req.user?.userType === 'user') {
      const medicine = item.medicineId && typeof item.medicineId === 'object'
        ? item.medicineId
        : undefined;

      const today = new Date().toISOString().slice(0, 10).replace(/-/g, '');
      const sellableAvailableQty = item.batches?.length
        ? item.batches.reduce(
            (total: number, batch: any) =>
              total + (batch.status === 'active' && batch.expiryDate >= today ? batch.availableQty : 0),
            0
          )
        : item.availableQty;

      return {
        _id: item._id,
        pharmacyId: item.pharmacyId,
        medicineId: medicine?._id || item.medicineId,
        availableQty: sellableAvailableQty,
        retailPrice: item.retailPrice,
        batchNumber: item.batchNumber,
        expiryDate: item.expiryDate,
        isActive: item.isActive,
        createdAt: item.createdAt,
        updatedAt: item.updatedAt,
        medicine: medicine
          ? {
              _id: medicine._id,
              name: medicine.name,
              genericName: medicine.genericName,
              brandName: medicine.brandName,
              dosageForm: medicine.dosageForm,
              strength: medicine.strength,
              manufacturer: medicine.manufacturer,
            }
          : undefined,
      } as Partial<InventoryResponseShape> & { medicine?: Record<string, unknown> };
    }

    return {
      _id: item._id,
      pharmacyId: item.pharmacyId,
      medicineId: item.medicineId,
      availableQty: item.availableQty,
      reservedQty: item.reservedQty,
      freeQty: item.freeQty,
      reorderThreshold: item.reorderThreshold,
      rackLocation: item.rackLocation,
      purchasePrice: item.purchasePrice,
      retailPrice: item.retailPrice,
      wholesalePrice: item.wholesalePrice,
      batchNumber: item.batchNumber,
      expiryDate: item.expiryDate,
      isActive: item.isActive,
      createdAt: item.createdAt,
      updatedAt: item.updatedAt,
      ...(req.query.includeBatches === 'true' ? { batches: item.batches || [] } : {}),
    };
  }

  addItem = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const pharmacyId = req.user?.pharmacyId || '';
    const data: CreateInventoryItemsRequest = {
      items: req.body.items.map((item: Record<string, unknown>) => ({ ...item, pharmacyId })),
    };
    const result = await this.inventoryService.saveItems(
      data,
      req.user?._id || '',
      req.user?.userType || 'pharmacy'
    );
    const responseData = result.map((item) => this.sanitizeInventoryItem(req, item));
    res.status(201).json({
      success: true,
      message: 'Inventory items saved',
      data: responseData,
    });
  };

  getItem = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const pharmacyId = req.user?.userType === 'pharmacy' ? req.user.pharmacyId : undefined;
    const result = await this.inventoryService.getItem(req.params.id, pharmacyId);
    res.status(200).json({ success: true, data: this.sanitizeInventoryItem(req, result) });
  };

  getByPharmacy = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const q = req.query as Record<string, string | undefined>;
    const isAdmin = req.user?.userType === 'admin';
    const isPharmacy = req.user?.userType === 'pharmacy';
    const isUser = req.user?.userType === 'user';
    const pharmacyId = isAdmin
      ? q.pharmacyId
      : isPharmacy
        ? req.user?.pharmacyId
        : q.pharmacyId;
    if (!pharmacyId) {
      throw new AppError({
        status: 400,
        code: 'PHARMACY_ID_REQUIRED',
        message: isPharmacy
          ? 'pharmacyId could not be resolved from pharmacy token'
          : 'pharmacyId is required for this inventory query',
      });
    }

    if (isUser) {
      await this.pharmacyService.getAccessibleById(pharmacyId, req.user);
    }

    const params: InventoryQueryParams = {
      pharmacyId,
      medicineId: q.medicineId,
      isActive: q.isActive !== undefined ? q.isActive === 'true' : undefined,
      lowStock: q.lowStock !== undefined ? q.lowStock === 'true' : undefined,
      search: q.search,
      includeBatches: q.includeBatches === 'true',
      page: q.page ? parseInt(q.page) : 1,
      limit: q.limit ? parseInt(q.limit) : 20,
    };

    const result = await this.inventoryService.getByPharmacy(params);
    res.status(200).json({
      success: true,
      data: result.data.map((item) => this.sanitizeInventoryItem(req, item)),
      pagination: { page: result.page, limit: params.limit, total: result.total, totalPages: result.totalPages },
    });
  };

  manualReserveStock = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const pharmacyId = req.user?.pharmacyId || '';
    const payload: ManualInventoryReservationRequest = req.body;
    const result = await this.inventoryService.manualReserveStock(pharmacyId, payload, {
      userId: req.user?._id,
      userRole: req.user?.userType,
    });
    res.status(200).json({
      success: true,
      message: 'Stock reserved',
      data: result.map((item) => this.sanitizeInventoryItem(req, item)),
    });
  };

  manualReleaseStock = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const pharmacyId = req.user?.pharmacyId || '';
    const payload: ManualInventoryReservationRequest = req.body;
    const result = await this.inventoryService.manualReleaseStock(pharmacyId, payload);
    res.status(200).json({
      success: true,
      message: 'Stock released',
      data: result.map((item) => this.sanitizeInventoryItem(req, item)),
    });
  };

  getQualityHolds = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const pharmacyId = req.user?.pharmacyId;
    const query: InventoryQualityWorklistQuery = {
      qualityStatus: req.query.qualityStatus as InventoryQualityHoldStatus | undefined,
      page: req.query.page === undefined ? 1 : Number(req.query.page),
      limit: req.query.limit === undefined ? 20 : Number(req.query.limit),
    };
    const result = await this.inventoryService.getQualityHolds(pharmacyId, query);
    res.status(200).json({
      success: true,
      pharmacyId,
      expiryEvaluation: 'not_evaluated',
      data: result.data,
      pagination: { page: result.page, limit: result.limit, total: result.total, totalPages: result.totalPages },
    });
  };

  getLowStock = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const pharmacyId =
      req.user?.userType === 'admin'
        ? ((req.query.pharmacyId as string) || '')
        : (req.user?.pharmacyId || '');
    if (!pharmacyId) {
      throw new AppError({ status: 400, code: 'PHARMACY_ID_REQUIRED', message: 'pharmacyId is required' });
    }
    const page = req.query.page ? parseInt(req.query.page as string) : 1;
    const limit = req.query.limit ? parseInt(req.query.limit as string) : 20;
    const result = await this.inventoryService.getLowStock(pharmacyId, page, limit);
    res.status(200).json({
      success: true,
      data: result.data.map((item) => this.sanitizeInventoryItem(req, item)),
      pagination: { page: result.page, limit, total: result.total, totalPages: result.totalPages },
    });
  };

  getAdjustmentHistory = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const pharmacyId =
      req.user?.userType === 'admin'
        ? ((req.query.pharmacyId as string) || '')
        : (req.user?.pharmacyId || '');
    if (!pharmacyId) {
      throw new AppError({ status: 400, code: 'PHARMACY_ID_REQUIRED', message: 'pharmacyId is required' });
    }
    const page = req.query.page ? parseInt(req.query.page as string) : 1;
    const limit = req.query.limit ? parseInt(req.query.limit as string) : 20;
    const result = await this.inventoryService.getAdjustmentHistory(pharmacyId, page, limit);
    res.status(200).json({
      success: true,
      data: result.data,
      pagination: { page: result.page, limit, total: result.total, totalPages: result.totalPages },
    });
  };
}

import { Service } from 'typedi';
import { ClientSession, Model, PipelineStage, Types } from 'mongoose';
import {
  InventoryItemModel,
  InventoryAdjustmentModel,
  InventoryReservationModel,
} from '@/modules/pharmacyInventory/model';
import {
  IInventoryItem,
  IInventoryAdjustment,
  IInventoryReservation,
  IInventoryBatchAllocation,
  InventoryQueryParams,
  INVENTORY_QUALITY_HOLD_STATUSES,
  InventoryQualityHoldStatus,
  InventoryQualityWorklistPage,
  InventoryQualityWorklistRow,
  PublicInventoryItemDto,
  PublicInventoryQueryParams,
} from '@/modules/pharmacyInventory/types';
import { PharmacyMedicineAvailabilityDto } from '@/modules/pharmacies/types';
import { BaseRepository } from '@/modules/common/repository';
import { buildContainsRegex } from '@/modules/common/utils/queryUtils';
import { AppError } from '@/modules/common/types';

@Service()
export class InventoryItemRepository extends BaseRepository<IInventoryItem> {
  constructor() {
    super(InventoryItemModel as Model<IInventoryItem>);
  }

  async findByPharmacyAndMedicine(
    pharmacyId: string,
    medicineId: string,
    session?: ClientSession
  ): Promise<IInventoryItem | null> {
    return this.findOne({ pharmacyId, medicineId }, session);
  }

  async adjustBatchStock(
    pharmacyId: string,
    medicineId: string,
    input: {
      batchNumber: string;
      expiryDate: string;
      quantityDelta: number;
      purchasePrice?: number;
      mrp?: number;
      retailPrice?: number;
      wholesalePrice?: number;
      reorderThreshold?: number;
      rackLocation?: string;
    },
    session: ClientSession
  ): Promise<{
    item: IInventoryItem;
    batchId: string;
    availableQtyBefore: number;
    availableQtyAfter: number;
  } | null> {
    let document = await InventoryItemModel.findOne({ pharmacyId, medicineId }).session(session);

    if (!document) {
      if (input.quantityDelta < 0) {
        return null;
      }
      document = new InventoryItemModel({
        pharmacyId,
        medicineId,
        availableQty: 0,
        reservedQty: 0,
        freeQty: 0,
        batches: [],
        isActive: true,
      });
      document.$session(session);
    }

    const batches = document.batches || [];
    let batch = batches.find(
      (candidate) =>
        candidate.batchNumber === input.batchNumber && candidate.expiryDate === input.expiryDate
    );

    if (!batch) {
      if (input.quantityDelta < 0) {
        return null;
      }
      document.batches!.push({
        batchNumber: input.batchNumber,
        expiryDate: input.expiryDate,
        receivedAt: new Date(),
        availableQty: 0,
        reservedQty: 0,
        freeQty: 0,
        purchasePrice: input.purchasePrice,
        mrp: input.mrp,
        retailPrice: input.retailPrice,
        wholesalePrice: input.wholesalePrice,
        status: 'active',
      });
      batch = document.batches![document.batches!.length - 1];
    }

    const availableQtyBefore = batch.availableQty;
    const availableQtyAfter = availableQtyBefore + input.quantityDelta;
    if (availableQtyAfter < 0 || document.availableQty + input.quantityDelta < 0) {
      return null;
    }

    batch.availableQty = availableQtyAfter;
    batch.purchasePrice = input.purchasePrice ?? batch.purchasePrice;
    batch.mrp = input.mrp ?? batch.mrp;
    batch.retailPrice = input.retailPrice ?? batch.retailPrice;
    batch.wholesalePrice = input.wholesalePrice ?? batch.wholesalePrice;
    if (
      batch.status !== 'recalled' &&
      batch.status !== 'quarantined' &&
      batch.status !== 'expired'
    ) {
      batch.status = availableQtyAfter === 0 && batch.reservedQty === 0 ? 'depleted' : 'active';
      batch.depletedAt = batch.status === 'depleted' ? new Date() : undefined;
    }

    document.availableQty += input.quantityDelta;
    document.reorderThreshold = input.reorderThreshold ?? document.reorderThreshold;
    document.rackLocation = input.rackLocation ?? document.rackLocation;
    document.purchasePrice = input.purchasePrice ?? document.purchasePrice;
    document.retailPrice = input.retailPrice ?? document.retailPrice;
    document.wholesalePrice = input.wholesalePrice ?? document.wholesalePrice;
    document.isActive = true;
    document.markModified('batches');

    const saved = await document.save({ session });
    return {
      item: saved.toObject() as IInventoryItem,
      batchId: String((batch as any)._id),
      availableQtyBefore,
      availableQtyAfter,
    };
  }

  async reserveBatches(
    pharmacyId: string,
    medicineId: string,
    quantity: number,
    session: ClientSession
  ): Promise<{ item: IInventoryItem; allocations: IInventoryBatchAllocation[] } | null> {
    const document = await InventoryItemModel.findOne({
      pharmacyId,
      medicineId,
      isActive: true,
    }).session(session);
    if (!document) return null;

    const today = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    const eligible = (document.batches || [])
      .filter(
        (batch) =>
          batch.status === 'active' && batch.expiryDate >= today && batch.availableQty > 0
      )
      .sort((a, b) =>
        a.expiryDate.localeCompare(b.expiryDate) ||
        a.receivedAt.getTime() - b.receivedAt.getTime() ||
        String((a as any)._id).localeCompare(String((b as any)._id))
      );

    if (eligible.reduce((sum, batch) => sum + batch.availableQty, 0) < quantity) {
      return null;
    }

    let remaining = quantity;
    const allocations: IInventoryBatchAllocation[] = [];
    for (const batch of eligible) {
      if (remaining === 0) break;
      const allocated = Math.min(remaining, batch.availableQty);
      batch.availableQty -= allocated;
      batch.reservedQty += allocated;
      allocations.push({
        batchId: String((batch as any)._id),
        batchNumber: batch.batchNumber,
        expiryDate: batch.expiryDate,
        quantity: allocated,
      });
      remaining -= allocated;
    }

    document.availableQty -= quantity;
    document.reservedQty += quantity;
    document.markModified('batches');
    const saved = await document.save({ session });
    return { item: saved.toObject() as IInventoryItem, allocations };
  }

  async releaseBatchAllocations(
    pharmacyId: string,
    medicineId: string,
    allocations: IInventoryBatchAllocation[],
    session: ClientSession
  ): Promise<IInventoryItem | null> {
    const document = await InventoryItemModel.findOne({ pharmacyId, medicineId }).session(session);
    if (!document) return null;

    let total = 0;
    const today = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    for (const allocation of allocations) {
      const batch = (document.batches || []).find(
        (candidate) => String((candidate as any)._id) === String(allocation.batchId)
      );
      if (!batch || batch.reservedQty < allocation.quantity) return null;
      batch.reservedQty -= allocation.quantity;
      batch.availableQty += allocation.quantity;
      if (
        batch.status !== 'recalled' &&
        batch.status !== 'quarantined' &&
        batch.status !== 'expired'
      ) {
        batch.status = batch.expiryDate < today ? 'expired' : 'active';
        batch.depletedAt = undefined;
      }
      total += allocation.quantity;
    }

    if (document.reservedQty < total) return null;
    document.reservedQty -= total;
    document.availableQty += total;
    document.markModified('batches');
    const saved = await document.save({ session });
    return saved.toObject() as IInventoryItem;
  }

  async consumeBatchAllocations(
    pharmacyId: string,
    medicineId: string,
    allocations: IInventoryBatchAllocation[],
    session: ClientSession
  ): Promise<IInventoryItem | null> {
    const document = await InventoryItemModel.findOne({ pharmacyId, medicineId }).session(session);
    if (!document) return null;

    let total = 0;
    const today = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    for (const allocation of allocations) {
      const batch = (document.batches || []).find(
        (candidate) => String((candidate as any)._id) === String(allocation.batchId)
      );
      if (
        !batch ||
        batch.status !== 'active' ||
        batch.expiryDate < today ||
        batch.reservedQty < allocation.quantity
      ) return null;
      batch.reservedQty -= allocation.quantity;
      if (batch.availableQty === 0 && batch.reservedQty === 0) {
        batch.status = 'depleted';
        batch.depletedAt = new Date();
      }
      total += allocation.quantity;
    }

    if (document.reservedQty < total) return null;
    document.reservedQty -= total;
    document.markModified('batches');
    const saved = await document.save({ session });
    return saved.toObject() as IInventoryItem;
  }

  async insertMany(items: Partial<IInventoryItem>[]): Promise<IInventoryItem[]> {
    const docs = await InventoryItemModel.insertMany(items, { ordered: true });
    return docs.map((doc) => doc.toObject());
  }

  // Single atomic create-or-update for one pharmacy/medicine pair. Adds
  // quantityDelta to availableQty (clamped at 0) and overwrites only the
  // provided fields, so concurrent saves cannot double-insert or overwrite
  // each other's quantity math. Pipeline update: the upsert base document is
  // built from the filter's equality fields (pharmacyId, medicineId).
  async atomicUpsertItem(
    pharmacyId: string,
    medicineId: string,
    quantityDelta: number,
    fields: Partial<IInventoryItem>,
    session?: ClientSession
  ): Promise<IInventoryItem> {
    const setStage: Record<string, unknown> = {
      availableQty: {
        $max: [0, { $add: [{ $ifNull: ['$availableQty', 0] }, quantityDelta] }],
      },
      reservedQty: { $ifNull: ['$reservedQty', 0] },
      freeQty: { $ifNull: ['$freeQty', 0] },
      reorderThreshold: { $ifNull: ['$reorderThreshold', 0] },
      createdAt: { $ifNull: ['$createdAt', '$$NOW'] },
      updatedAt: '$$NOW',
    };

    for (const [key, value] of Object.entries(fields)) {
      if (value !== undefined) {
        setStage[key] = { $literal: value };
      }
    }

    const item = await InventoryItemModel.findOneAndUpdate(
      {
        pharmacyId: new Types.ObjectId(pharmacyId),
        medicineId: new Types.ObjectId(medicineId),
      },
      [{ $set: setStage }] as any,
      { new: true, upsert: true, session }
    ).lean();

    return item as IInventoryItem;
  }

  async findQualityHolds(pharmacyId: unknown, query: unknown): Promise<InventoryQualityWorklistPage> {
    if (typeof pharmacyId !== 'string' || !/^[0-9a-f]{24}$/.test(pharmacyId)) {
      throw new AppError({ status: 403, code: 'FORBIDDEN', message: 'Access denied' });
    }
    const invalidQuery = () => new AppError({
      status: 400, code: 'VALIDATION_ERROR', message: 'Invalid quality worklist query',
    });
    const isRecord = (value: unknown): value is Record<string, unknown> =>
      !!value && typeof value === 'object' && !Array.isArray(value) &&
      [Object.prototype, null].includes(Object.getPrototypeOf(value)) &&
      Reflect.ownKeys(value).every(key => typeof key === 'string' && 'value' in Object.getOwnPropertyDescriptor(value, key)!);
    if (!isRecord(query)) throw invalidQuery();
    for (const key of Reflect.ownKeys(query)) {
      if (
        typeof key !== 'string' || !['qualityStatus', 'page', 'limit'].includes(key) ||
        !('value' in Object.getOwnPropertyDescriptor(query, key)!)
      ) throw invalidQuery();
    }
    const qualityStatus = Object.getOwnPropertyDescriptor(query, 'qualityStatus')?.value;
    const requestedPage = Object.getOwnPropertyDescriptor(query, 'page')?.value;
    const requestedLimit = Object.getOwnPropertyDescriptor(query, 'limit')?.value;
    const page = requestedPage === undefined ? 1 : requestedPage;
    const limit = requestedLimit === undefined ? 20 : requestedLimit;
    if (
      (qualityStatus !== undefined && !INVENTORY_QUALITY_HOLD_STATUSES.some(status => status === qualityStatus)) ||
      typeof page !== 'number' || !Number.isSafeInteger(page) || page < 1 || page > 1000 ||
      typeof limit !== 'number' || !Number.isSafeInteger(limit) || limit < 1 || limit > 50
    ) throw invalidQuery();
    const statuses = qualityStatus === undefined
      ? [...INVENTORY_QUALITY_HOLD_STATUSES]
      : [qualityStatus as InventoryQualityHoldStatus];
    const skip = (page - 1) * limit;
    const pipeline: PipelineStage[] = [
      {
        $match: {
          pharmacyId: new Types.ObjectId(pharmacyId),
          batches: { $elemMatch: { status: { $in: statuses } } },
          $expr: { $and: [{ $isArray: '$batches' }, { $eq: [{ $type: '$pharmacyId' }, 'objectId'] }] },
        },
      },
      {
        $project: {
          _id: 1, medicineId: 1, isActive: 1, rackLocation: 1,
          batches: {
            $map: {
              input: '$batches', as: 'batch',
              in: {
                _id: '$$batch._id', batchNumber: '$$batch.batchNumber', expiryDate: '$$batch.expiryDate',
                status: '$$batch.status', availableQty: '$$batch.availableQty',
                reservedQty: '$$batch.reservedQty', freeQty: '$$batch.freeQty',
              },
            },
          },
        },
      },
      { $unwind: { path: '$batches', includeArrayIndex: 'batchPosition' } },
      { $match: { 'batches.status': { $in: statuses }, $expr: { $eq: [{ $type: '$batches.status' }, 'string'] } } },
      {
        $facet: {
          metadata: [{ $count: 'total' }],
          data: [
            { $sort: { _id: 1, batchPosition: 1 } },
            { $skip: skip },
            { $limit: limit },
            {
              $lookup: {
                from: 'medicines', let: { medicineId: '$medicineId' },
                pipeline: [
                  { $match: { $expr: { $eq: ['$_id', '$$medicineId'] } } },
                  { $project: { _id: 0, name: 1 } },
                  { $limit: 1 },
                ],
                as: 'medicine',
              },
            },
            {
              $project: {
                _id: 0, inventoryItemId: '$_id', medicineId: 1,
                medicineName: { $arrayElemAt: ['$medicine.name', 0] },
                inventoryIsActive: '$isActive', rackLocation: 1,
                batchId: '$batches._id', batchPosition: 1,
                batchNumberRaw: '$batches.batchNumber', expiryDateRaw: '$batches.expiryDate',
                storedQualityStatus: '$batches.status', availableQty: '$batches.availableQty',
                reservedQty: '$batches.reservedQty', freeQty: '$batches.freeQty',
              },
            },
          ],
        },
      },
    ];
    const result = await InventoryItemModel.aggregate<unknown>(pipeline)
      .option({ maxTimeMS: 2000, allowDiskUse: false }).exec();
    const unavailable = () => new AppError({
      status: 503, code: 'QUALITY_WORKLIST_UNAVAILABLE', message: 'Quality worklist is unavailable',
    });
    if (!Array.isArray(result) || result.length !== 1) throw unavailable();
    const facet = result[0];
    if (
      !isRecord(facet) || Reflect.ownKeys(facet).length !== 2 ||
      !Array.isArray(facet.data) || !Array.isArray(facet.metadata) ||
      facet.metadata.length > 1 || facet.data.length > limit
    ) throw unavailable();
    let total = 0;
    if (facet.metadata.length) {
      const count = facet.metadata[0];
      if (!isRecord(count) || Reflect.ownKeys(count).length !== 1 || typeof count.total !== 'number' || !Number.isSafeInteger(count.total) || count.total < 0) throw unavailable();
      total = count.total;
    }
    if (facet.data.length !== Math.min(limit, Math.max(0, total - skip))) throw unavailable();
    const objectId = (value: unknown): string | null => value instanceof Types.ObjectId ? value.toHexString() : null;
    const text = (value: unknown, max: number): string | null => typeof value === 'string' && value.length <= max ? value : null;
    const quantity = (value: unknown): number | null => typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 ? value : null;
    const data: InventoryQualityWorklistRow[] = facet.data.map((row: unknown) => {
      if (!isRecord(row)) throw unavailable();
      const inventoryItemId = objectId(row.inventoryItemId);
      const storedQualityStatus = statuses.find(status => status === row.storedQualityStatus);
      if (!inventoryItemId || storedQualityStatus === undefined || typeof row.batchPosition !== 'number' || !Number.isSafeInteger(row.batchPosition) || row.batchPosition < 0) throw unavailable();
      return {
        inventoryItemId, medicineId: objectId(row.medicineId), medicineName: text(row.medicineName, 200),
        inventoryIsActive: typeof row.inventoryIsActive === 'boolean' ? row.inventoryIsActive : null,
        rackLocation: text(row.rackLocation, 100), batchId: objectId(row.batchId), batchPosition: row.batchPosition,
        batchNumberRaw: text(row.batchNumberRaw, 100), expiryDateRaw: text(row.expiryDateRaw, 32),
        storedQualityStatus, availableQty: quantity(row.availableQty), reservedQty: quantity(row.reservedQty), freeQty: quantity(row.freeQty),
      };
    });
    return { data, page, limit, total, totalPages: Math.ceil(total / limit) };
  }

  async findWithPagination(
    filter: InventoryQueryParams,
    page: number = 1,
    limit: number = 20
  ): Promise<{ data: IInventoryItem[]; total: number; page: number; totalPages: number }> {
    const query: any = {};
    if (filter.pharmacyId) query.pharmacyId = new Types.ObjectId(filter.pharmacyId);
    if (filter.medicineId) query.medicineId = new Types.ObjectId(filter.medicineId);
    if (filter.isActive !== undefined) query.isActive = filter.isActive;
    if (filter.lowStock) {
      query.$expr = { $lte: ['$availableQty', '$reorderThreshold'] };
    }

    const skip = (page - 1) * limit;
    const pipeline: any[] = [{ $match: query }];

    if (filter.search) {
      const regex = buildContainsRegex(filter.search);
      pipeline.push(
        {
          $lookup: {
            from: 'medicines',
            localField: 'medicineId',
            foreignField: '_id',
            as: 'medicine',
          },
        },
        { $unwind: '$medicine' },
        {
          $match: {
            $or: [
              { 'medicine.name': regex },
              { 'medicine.genericName': regex },
              { 'medicine.brandName': regex },
              { 'medicine.category': regex },
              { 'medicine.manufacturer': regex },
            ],
          },
        }
      );
    }

    const countPipeline = [...pipeline, { $count: 'total' }];
    const dataPipeline = [
      ...pipeline,
      { $sort: { updatedAt: -1 } },
      { $skip: skip },
      { $limit: limit },
    ];

    if (filter.search) {
      dataPipeline.push({
        $addFields: {
          medicineId: {
            _id: '$medicine._id',
            name: '$medicine.name',
            genericName: '$medicine.genericName',
            brandName: '$medicine.brandName',
            dosageForm: '$medicine.dosageForm',
            strength: '$medicine.strength',
          },
        },
      });
      dataPipeline.push({ $project: { medicine: 0 } });
    } else {
      dataPipeline.push({
        $lookup: {
          from: 'medicines',
          localField: 'medicineId',
          foreignField: '_id',
          as: 'medicine',
        },
      });
      dataPipeline.push({ $unwind: { path: '$medicine', preserveNullAndEmptyArrays: true } });
      dataPipeline.push({
        $addFields: {
          medicineId: {
            _id: '$medicine._id',
            name: '$medicine.name',
            genericName: '$medicine.genericName',
            brandName: '$medicine.brandName',
            dosageForm: '$medicine.dosageForm',
            strength: '$medicine.strength',
          },
        },
      });
      dataPipeline.push({ $project: { medicine: 0 } });
    }

    const [data, countResult] = await Promise.all([
      InventoryItemModel.aggregate(dataPipeline),
      InventoryItemModel.aggregate(countPipeline),
    ]);

    const total = countResult[0]?.total ?? 0;

    return { data, total, page, totalPages: Math.ceil(total / limit) };
  }

  async findMedicineAvailability(
    {
      medicineId,
      latitude,
      longitude,
      radiusKm,
      page = 1,
      limit = 20,
    }: {
      medicineId: string;
      latitude?: number;
      longitude?: number;
      radiusKm?: number;
      page?: number;
      limit?: number;
    },
    includeWholesalePrice: boolean
  ): Promise<{
    data: PharmacyMedicineAvailabilityDto[];
    total: number;
    page: number;
    totalPages: number;
  }> {
    const today = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    const sellableBatchQuantity = {
      $sum: {
        $map: {
          input: { $ifNull: ['$batches', []] },
          as: 'batch',
          in: {
            $cond: [
              {
                $and: [
                  { $eq: ['$$batch.status', 'active'] },
                  { $gte: ['$$batch.expiryDate', today] },
                ],
              },
              '$$batch.availableQty',
              0,
            ],
          },
        },
      },
    };
    const pipeline: any[] = [
      {
        $match: {
          medicineId: new Types.ObjectId(medicineId),
          isActive: true,
        },
      },
      {
        $addFields: {
          sellableAvailableQty: {
            $cond: [
              { $gt: [{ $size: { $ifNull: ['$batches', []] } }, 0] },
              sellableBatchQuantity,
              '$availableQty',
            ],
          },
        },
      },
      { $match: { sellableAvailableQty: { $gt: 0 } } },
      {
        $lookup: {
          from: 'pharmacies',
          localField: 'pharmacyId',
          foreignField: '_id',
          as: 'pharmacy',
        },
      },
      { $unwind: '$pharmacy' },
      {
        $match: {
          'pharmacy.isActive': true,
          'pharmacy.isVerified': true,
        },
      },
      {
        $lookup: {
          from: 'medicines',
          localField: 'medicineId',
          foreignField: '_id',
          as: 'medicine',
        },
      },
      { $unwind: '$medicine' },
    ];

    if (latitude !== undefined && longitude !== undefined) {
      const toRadians = Math.PI / 180;
      pipeline.push({
        $match: {
          'pharmacy.latitude': { $type: 'number' },
          'pharmacy.longitude': { $type: 'number' },
        },
      });
      pipeline.push({
        $addFields: {
          distanceKm: {
            $multiply: [
              6371,
              {
                $acos: {
                  $min: [
                    1,
                    {
                      $max: [
                        -1,
                        {
                          $add: [
                            {
                              $multiply: [
                                { $sin: { $multiply: ['$pharmacy.latitude', toRadians] } },
                                Math.sin(latitude * toRadians),
                              ],
                            },
                            {
                              $multiply: [
                                { $cos: { $multiply: ['$pharmacy.latitude', toRadians] } },
                                Math.cos(latitude * toRadians),
                                {
                                  $cos: {
                                    $multiply: [
                                      { $subtract: ['$pharmacy.longitude', longitude] },
                                      toRadians,
                                    ],
                                  },
                                },
                              ],
                            },
                          ],
                        },
                      ],
                    },
                  ],
                },
              },
            ],
          },
        },
      });

      if (radiusKm !== undefined) {
        pipeline.push({
          $match: {
            distanceKm: { $lte: radiusKm },
          },
        });
      }
    }

    const projection: Record<string, unknown> = {
      _id: 0,
      pharmacyId: { $toString: '$pharmacy._id' },
      medicineId: { $toString: '$medicine._id' },
      pharmacyName: '$pharmacy.name',
      pharmacyNickname: '$pharmacy.nickname',
      address: '$pharmacy.address',
      city: '$pharmacy.city',
      state: '$pharmacy.state',
      pincode: '$pharmacy.pincode',
      latitude: '$pharmacy.latitude',
      longitude: '$pharmacy.longitude',
      profilePictureUrl: '$pharmacy.profilePictureUrl',
      pickupAvailable: '$pharmacy.pickupAvailable',
      deliveryAvailable: '$pharmacy.deliveryAvailable',
      medicineName: '$medicine.name',
      genericName: '$medicine.genericName',
      brandName: '$medicine.brandName',
      dosageForm: '$medicine.dosageForm',
      strength: '$medicine.strength',
      manufacturer: '$medicine.manufacturer',
      availableQty: '$sellableAvailableQty',
      retailPrice: '$retailPrice',
      distanceKm: '$distanceKm',
    };

    if (includeWholesalePrice) {
      projection.wholesalePrice = '$wholesalePrice';
    }

    const sortStage =
      latitude !== undefined && longitude !== undefined
        ? { distanceKm: 1, retailPrice: 1, updatedAt: -1 }
        : { retailPrice: 1, updatedAt: -1 };

    const countPipeline = [...pipeline, { $count: 'total' }];
    const dataPipeline = [
      ...pipeline,
      { $sort: sortStage },
      { $project: projection },
      { $skip: (page - 1) * limit },
      { $limit: limit },
    ];

    const [data, countResult] = await Promise.all([
      InventoryItemModel.aggregate(dataPipeline),
      InventoryItemModel.aggregate(countPipeline),
    ]);

    const total = countResult[0]?.total ?? 0;
    return {
      data,
      total,
      page,
      totalPages: Math.ceil(total / limit),
    };
  }

  async findPublicInventoryByPharmacy(
    {
      pharmacyId,
      search,
      page = 1,
      limit = 20,
    }: PublicInventoryQueryParams,
    includeWholesalePrice: boolean
  ): Promise<{
    data: PublicInventoryItemDto[];
    total: number;
    page: number;
    totalPages: number;
  }> {
    const today = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    const pipeline: any[] = [
      {
        $match: {
          pharmacyId: new Types.ObjectId(pharmacyId),
          isActive: true,
        },
      },
      {
        $addFields: {
          sellableAvailableQty: {
            $cond: [
              { $gt: [{ $size: { $ifNull: ['$batches', []] } }, 0] },
              {
                $sum: {
                  $map: {
                    input: { $ifNull: ['$batches', []] },
                    as: 'batch',
                    in: {
                      $cond: [
                        {
                          $and: [
                            { $eq: ['$$batch.status', 'active'] },
                            { $gte: ['$$batch.expiryDate', today] },
                          ],
                        },
                        '$$batch.availableQty',
                        0,
                      ],
                    },
                  },
                },
              },
              '$availableQty',
            ],
          },
        },
      },
      { $match: { sellableAvailableQty: { $gt: 0 } } },
      {
        $lookup: {
          from: 'medicines',
          localField: 'medicineId',
          foreignField: '_id',
          as: 'medicine',
        },
      },
      { $unwind: '$medicine' },
      {
        $match: {
          'medicine.isActive': true,
        },
      },
    ];

    if (search) {
      const regex = buildContainsRegex(search);
      pipeline.push({
        $match: {
          $or: [
            { 'medicine.name': regex },
            { 'medicine.genericName': regex },
            { 'medicine.brandName': regex },
            { 'medicine.manufacturer': regex },
            { 'medicine.category': regex },
          ],
        },
      });
    }

    const projection: Record<string, unknown> = {
      _id: 0,
      inventoryItemId: { $toString: '$_id' },
      pharmacyId: { $toString: '$pharmacyId' },
      medicineId: { $toString: '$medicine._id' },
      name: '$medicine.name',
      genericName: '$medicine.genericName',
      brandName: '$medicine.brandName',
      category: '$medicine.category',
      dosageForm: '$medicine.dosageForm',
      strength: '$medicine.strength',
      manufacturer: '$medicine.manufacturer',
      prescriptionRequired: '$medicine.prescriptionRequired',
      availableQty: '$sellableAvailableQty',
      retailPrice: '$retailPrice',
      batchNumber: '$batchNumber',
      expiryDate: '$expiryDate',
    };

    if (includeWholesalePrice) {
      projection.wholesalePrice = '$wholesalePrice';
    }

    const countPipeline = [...pipeline, { $count: 'total' }];
    const dataPipeline = [
      ...pipeline,
      { $sort: { 'medicine.name': 1, retailPrice: 1, updatedAt: -1 } },
      { $project: projection },
      { $skip: (page - 1) * limit },
      { $limit: limit },
    ];

    const [data, countResult] = await Promise.all([
      InventoryItemModel.aggregate(dataPipeline),
      InventoryItemModel.aggregate(countPipeline),
    ]);

    const total = countResult[0]?.total ?? 0;
    return {
      data,
      total,
      page,
      totalPages: Math.ceil(total / limit),
    };
  }

  // Atomically reserves qty: decrements availableQty, increments reservedQty
  async atomicReserve(
    pharmacyId: string,
    medicineId: string,
    qty: number
  ): Promise<IInventoryItem | null> {
    return InventoryItemModel.findOneAndUpdate(
      {
        pharmacyId,
        medicineId,
        isActive: true,
        availableQty: { $gte: qty },
      },
      {
        $inc: { availableQty: -qty, reservedQty: qty },
      },
      { new: true }
    ).lean();
  }

  // Atomically releases reserved qty back to available
  async atomicRelease(
    pharmacyId: string,
    medicineId: string,
    qty: number
  ): Promise<IInventoryItem | null> {
    return InventoryItemModel.findOneAndUpdate(
      {
        pharmacyId,
        medicineId,
        reservedQty: { $gte: qty },
      },
      {
        $inc: { availableQty: qty, reservedQty: -qty },
      },
      { new: true }
    ).lean();
  }

  // Deducts reserved qty (order fulfilled): decrements reservedQty only
  async atomicDeduct(
    pharmacyId: string,
    medicineId: string,
    qty: number
  ): Promise<IInventoryItem | null> {
    return InventoryItemModel.findOneAndUpdate(
      {
        pharmacyId,
        medicineId,
        reservedQty: { $gte: qty },
      },
      {
        $inc: { reservedQty: -qty },
      },
      { new: true }
    ).lean();
  }

  // Returns qty to available (order cancelled after deduct)
  async atomicReturn(
    pharmacyId: string,
    medicineId: string,
    qty: number,
    session?: ClientSession
  ): Promise<IInventoryItem | null> {
    return InventoryItemModel.findOneAndUpdate(
      { pharmacyId, medicineId, isActive: true },
      { $inc: { availableQty: qty } },
      { new: true, session }
    ).lean();
  }

  // Deducts available qty directly (used when prepaid order payment succeeds)
  async atomicConsumeAvailable(
    pharmacyId: string,
    medicineId: string,
    qty: number,
    session?: ClientSession
  ): Promise<IInventoryItem | null> {
    return InventoryItemModel.findOneAndUpdate(
      {
        pharmacyId,
        medicineId,
        isActive: true,
        availableQty: { $gte: qty },
      },
      {
        $inc: { availableQty: -qty },
      },
      { new: true, session }
    ).lean();
  }

  // Adds free qty (promotional/bonus units)
  async atomicAddFree(
    pharmacyId: string,
    medicineId: string,
    qty: number
  ): Promise<IInventoryItem | null> {
    return InventoryItemModel.findOneAndUpdate(
      { pharmacyId, medicineId },
      { $inc: { freeQty: qty } },
      { new: true }
    ).lean();
  }
}

@Service()
export class InventoryAdjustmentRepository extends BaseRepository<IInventoryAdjustment> {
  constructor() {
    super(InventoryAdjustmentModel as Model<IInventoryAdjustment>);
  }

  async findByPharmacy(
    pharmacyId: string,
    page: number = 1,
    limit: number = 20
  ): Promise<{ data: IInventoryAdjustment[]; total: number; page: number; totalPages: number }> {
    const skip = (page - 1) * limit;
    const [data, total] = await Promise.all([
      InventoryAdjustmentModel.find({ pharmacyId })
        .populate('medicineId', 'name genericName')
        .sort({ createdAt: -1 })
        .skip(skip)
        .limit(limit)
        .lean(),
      InventoryAdjustmentModel.countDocuments({ pharmacyId }),
    ]);
    return { data, total, page, totalPages: Math.ceil(total / limit) };
  }
}

@Service()
export class InventoryReservationRepository extends BaseRepository<IInventoryReservation> {
  constructor() {
    super(InventoryReservationModel as Model<IInventoryReservation>);
  }

  async insertMany(items: Partial<IInventoryReservation>[]): Promise<IInventoryReservation[]> {
    const docs = await InventoryReservationModel.insertMany(items, { ordered: true });
    return docs.map((doc) => doc.toObject());
  }

  async findActiveManualByMedicineIds(
    pharmacyId: string,
    medicineIds: string[]
  ): Promise<IInventoryReservation[]> {
    return InventoryReservationModel.find({
      pharmacyId,
      reservationType: 'manual',
      status: 'active',
      remainingQty: { $gt: 0 },
      medicineId: { $in: medicineIds },
    })
      .sort({ createdAt: 1, _id: 1 })
      .lean();
  }
}

