export const requirePharmacy = (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): void => {
  try {
    if (!req.user) {
      throw new AppError({
        status: 401,
        code: 'UNAUTHORIZED',
        message: 'Authentication is required',
      });
    }

    if (req.user.userType !== 'pharmacy') {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'Pharmacy access is required',
      });
    }

    const pharmacyId = req.user.pharmacyId || req.user._id;
    if (!pharmacyId) {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'Pharmacy account must be linked to a pharmacy profile',
      });
    }

    req.user.pharmacyId = pharmacyId;
    next();
  } catch (error) {
    next(error);
  }
};

export const requireAdminOrPharmacy = (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): void => {
  try {
    if (!req.user) {
      throw new AppError({
        status: 401,
        code: 'UNAUTHORIZED',
        message: 'Authentication is required',
      });
    }

    if (req.user.userType === 'admin') {
      return next();
    }

    if (req.user.userType === 'pharmacy') {
      const pharmacyId = req.user.pharmacyId || req.user._id;
      if (!pharmacyId) {
        throw new AppError({
          status: 403,
          code: 'FORBIDDEN',
          message: 'Pharmacy account must be linked to a pharmacy profile',
        });
      }

      req.user.pharmacyId = pharmacyId;
      return next();
    }

    throw new AppError({
      status: 403,
      code: 'FORBIDDEN',
      message: 'Admin or pharmacy access is required',
    });
  } catch (error) {
    next(error);
  }
};

const assertOperationalPharmacy = async (req: AuthRequest): Promise<void> => {
  const pharmacyId = req.user?.pharmacyId || req.user?._id;
  if (!pharmacyId) {
    throw new AppError({
      status: 403,
      code: 'PHARMACY_PROFILE_REQUIRED',
      message: 'Pharmacy account must be linked to a pharmacy profile',
    });
  }

  const pharmacy = await PharmacyModel.findById(pharmacyId)
    .select('_id isActive isVerified archivedAt')
    .lean();

  if (!pharmacy || pharmacy.archivedAt || pharmacy.isActive === false) {
    throw new AppError({
      status: 403,
      code: 'PHARMACY_INACTIVE',
      message: 'This pharmacy account is inactive',
    });
  }

  if (!pharmacy.isVerified) {
    throw new AppError({
      status: 403,
      code: 'PHARMACY_NOT_VERIFIED',
      message: 'Pharmacy verification is required for this operation',
    });
  }

  req.user!.pharmacyId = String(pharmacy._id);
};

/** Pharmacy business operations use this; onboarding/profile routes use requirePharmacy. */
export const requireOperationalPharmacy = async (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): Promise<void> => {
  try {
    if (!req.user) {
      throw new AppError({ status: 401, code: 'UNAUTHORIZED', message: 'Authentication is required' });
    }
    if (req.user.userType !== 'pharmacy') {
      throw new AppError({ status: 403, code: 'FORBIDDEN', message: 'Pharmacy access is required' });
    }
    await assertOperationalPharmacy(req);
    next();
  } catch (error) {
    next(error);
  }
};

export const requireAdminOrOperationalPharmacy = async (
  req: AuthRequest,
  _res: Response,
  next: NextFunction
): Promise<void> => {
  try {
    if (!req.user) {
      throw new AppError({ status: 401, code: 'UNAUTHORIZED', message: 'Authentication is required' });
    }
    if (req.user.userType === 'admin') {
      next();
      return;
    }
    if (req.user.userType !== 'pharmacy') {
      throw new AppError({
        status: 403,
        code: 'FORBIDDEN',
        message: 'Admin or verified pharmacy access is required',
      });
    }
    await assertOperationalPharmacy(req);
    next();
  } catch (error) {
    next(error);
  }
};

import {
  ClientSession,
  FilterQuery,
  LeanDocument,
  QueryOptions,
  SaveOptions,
  UpdateQuery,
  Model,
} from 'mongoose';

interface FindOptions {
  limit?: number;
  skip?: number;
  select?: any;
  sort?: any;
}

export default class BaseRepository<T> {
  private model: Model<T>;

  constructor(model: Model<T>) {
    this.model = model;
  }

  get = async (id: string, session?: ClientSession): Promise<LeanDocument<T> | null> => {
    const query = this.model.findById(id);
    if (session) {
      query.session(session);
    }
    return query.lean();
  };

  findOne = async (query: FilterQuery<T>, session?: ClientSession): Promise<LeanDocument<T> | null> => {
    const dbQuery = this.model.findOne(query);
    if (session) {
      dbQuery.session(session);
    }
    return dbQuery.lean();
  };

  findById = async (_id: string, session?: ClientSession): Promise<LeanDocument<T> | null> => {
    const query = this.model.findById(_id);
    if (session) {
      query.session(session);
    }
    return query.lean();
  };

  findAll = async (
    filter: FilterQuery<T> = {},
    options: FindOptions = {}
  ): Promise<LeanDocument<T>[]> => {
    const query = this.model.find(filter);
    if (options.limit) query.limit(options.limit);
    if (options.skip) query.skip(options.skip);
    if (options.select) query.select(options.select);
    if (options.sort) query.sort(options.sort);
    return query.lean();
  };

  save = async (data: Partial<T>, options: SaveOptions = {}): Promise<LeanDocument<T>> => {
    const instance = new this.model(data);
    return (await instance.save(options)).toObject();
  };

  update = async (
    query: FilterQuery<T>,
    data: Partial<T> | UpdateQuery<T>,
    options: QueryOptions = { new: true }
  ): Promise<LeanDocument<T> | null> => {
    return this.model.findOneAndUpdate(query, data, options).lean();
  };

  delete = async (query: FilterQuery<T>, options: QueryOptions = {}): Promise<void> => {
    await this.model.deleteOne(query, options);
  };

  deleteMany = async (query: FilterQuery<T>, options: QueryOptions = {}): Promise<void> => {
    await this.model.deleteMany(query, options);
  };

  updateMany = async (
    query: FilterQuery<T>,
    data: Partial<T> | UpdateQuery<T>,
    options: QueryOptions = {}
  ): Promise<any> => {
    return await this.model.updateMany(query, data, options);
  };

  findMany = (filter: FilterQuery<T>, projection?: any) => {
    return this.model.find(filter, projection);
  };
}

import { Request, Response, NextFunction } from 'express';
import Joi from 'joi';
import { AppError } from '../types';

type ValidationSource = 'body' | 'query' | 'params';

/**
 * Validation middleware factory
 * @param schema - Joi validation schema
 * @param source - Where to validate from (body, query, params)
 */
export const validate = (
  schema: Joi.Schema,
  source: ValidationSource = 'body'
) => {
  return (req: Request, _res: Response, next: NextFunction) => {
    const { error, value } = schema.validate(req[source], {
      abortEarly: false,
      stripUnknown: true,
    });

    if (error) {
      const errorMessages = error.details.map((detail) => detail.message).join(', ');
      throw new AppError({
        status: 400,
        code: 'VALIDATION_ERROR',
        message: errorMessages,
      });
    }

    // Replace req[source] with validated and sanitized value
    req[source] = value;
    next();
  };
};

import { Request, Response, NextFunction } from 'express';
import { CustomError } from '@/modules/common/types';
import logger from '@/services/logger';
import { isDuplicateKeyError } from '@/modules/common/utils/mongoErrors';

export const errorHandler = (
  err: CustomError,
  _req: Request,
  res: Response,
  _next: NextFunction
) => {
  // TODO: here add logger.error
  logger.error(err.message, {});

  if (isDuplicateKeyError(err)) {
    return res.status(409).json({
      error: 409,
      message: 'This record already exists. Please refresh and try again.',
      code: 'DUPLICATE_RESOURCE',
    });
  }

  // if no status or message in error use default 500 code and message
  const statusCode = err.status ?? 500;
  const message = err.message || 'Something went wrong.';

  // returns error status code and message
  return res.status(statusCode).json({
    error: statusCode,
    message: message,
    code: err?.code,
  });
};

