import { Schema, model, Model } from 'mongoose';
import { IWallet, IWalletTransaction } from '@/modules/wallet/types';

// Wallet Schema - One wallet per user
const walletSchema = new Schema<IWallet>(
  {
    userId: {
      type: String,
      required: true,
      unique: true,
      index: true,
    }, // User who owns this wallet (one wallet per user)
    balance: {
      type: Number,
      required: true,
      default: 0,
      min: 0,
    }, // Current wallet balance (calculated from transactions, should always be >= 0)
    isActive: {
      type: Boolean,
      default: true,
      index: true,
    }, // Whether wallet is active
  },
  {
    timestamps: true,
  }
);

// Wallet Transaction Schema - Transaction history
const walletTransactionSchema = new Schema<IWalletTransaction>(
  {
    userId: {
      type: String,
      required: true,
      index: true,
    }, // User who owns the wallet
    walletId: {
      type: String,
      index: true,
    }, // Reference to wallet (optional, can be derived from userId)
    transactionType: {
      type: String,
      enum: ['credit', 'debit', 'refund', 'cashback', 'promotion'],
      required: true,
      index: true,
    }, // Type: 'credit' (adds to balance), 'debit' (deducts from balance), 'refund', 'cashback', 'promotion'
    amount: {
      type: Number,
      required: true,
      min: 0,
    }, // Transaction amount (always positive, type determines if it's added or deducted)
    balanceBefore: {
      type: Number,
      required: true,
      min: 0,
    }, // Wallet balance before this transaction
    balanceAfter: {
      type: Number,
      required: true,
      min: 0,
    }, // Wallet balance after this transaction
    status: {
      type: String,
      enum: ['pending', 'completed', 'failed', 'cancelled'],
      default: 'completed',
      index: true,
    }, // Transaction status
    referenceType: {
      type: String,
      trim: true,
      index: true,
    }, // Type of reference: 'booking', 'refund', 'cashback', 'promotion', etc.
    referenceId: {
      type: String,
      trim: true,
      index: true,
    }, // ID of the reference entity (bookingId, refundId, etc.)
    description: {
      type: String,
      trim: true,
    }, // Description of the transaction
    notes: {
      type: String,
      trim: true,
    }, // Additional notes
    transactionDate: {
      type: String,
      match: /^\d{8}$/, // YYYYMMDD format
      index: true,
    }, // Date of transaction (YYYYMMDD format)
  },
  {
    timestamps: true,
  }
);

// Indexes for better query performance
walletSchema.index({ userId: 1, isActive: 1 });
walletSchema.index({ balance: 1 });

walletTransactionSchema.index({ userId: 1, transactionType: 1 });
walletTransactionSchema.index({ userId: 1, status: 1 });
walletTransactionSchema.index({ userId: 1, transactionDate: 1 });
walletTransactionSchema.index({ referenceType: 1, referenceId: 1 });
walletTransactionSchema.index({ transactionDate: 1, status: 1 });
walletTransactionSchema.index({ createdAt: -1 }); // For recent transactions
walletTransactionSchema.index(
  { userId: 1, transactionType: 1, referenceType: 1, referenceId: 1 },
  {
    unique: true,
    partialFilterExpression: {
      transactionType: 'refund',
      referenceType: 'pharmacy_order',
      referenceId: { $exists: true, $type: 'string' },
    },
  }
);

const WalletModel: Model<IWallet> = model<IWallet>('Wallet', walletSchema);
const WalletTransactionModel: Model<IWalletTransaction> = model<IWalletTransaction>(
  'WalletTransaction',
  walletTransactionSchema
);

export { WalletModel, WalletTransactionModel };
export default WalletModel;

import { Service } from 'typedi';
import { ClientSession, Model } from 'mongoose';
import { WalletModel, WalletTransactionModel } from '@/modules/wallet/model';
import {
  IWallet,
  IWalletTransaction,
  WalletQueryParams,
  WalletTransactionQueryParams,
} from '@/modules/wallet/types';
import { BaseRepository } from '@/modules/common/repository';

@Service()
export class WalletRepository extends BaseRepository<IWallet> {
  constructor() {
    super(WalletModel as Model<IWallet>);
  }

  async findByUserId(userId: string): Promise<IWallet | null> {
    return this.findOne({ userId });
  }

  async atomicCredit(
    userId: string,
    amount: number,
    session?: ClientSession
  ): Promise<IWallet | null> {
    return WalletModel.findOneAndUpdate(
      { userId, isActive: true },
      { $inc: { balance: amount } },
      { new: true, session }
    ).lean();
  }

  async findWithPagination(
    filter: WalletQueryParams = {},
    page: number = 1,
    limit: number = 10
  ): Promise<{ data: IWallet[]; total: number; page: number; totalPages: number }> {
    const query: any = {};

    if (filter.userId) {
      query.userId = filter.userId;
    }

    if (filter.isActive !== undefined) {
      query.isActive = filter.isActive;
    }

    const skip = (page - 1) * limit;
    const sort: any = {};

    if (filter.sortBy) {
      sort[filter.sortBy] = filter.sortOrder === 'desc' ? -1 : 1;
    } else {
      sort.createdAt = -1;
    }

    const [data, total] = await Promise.all([
      this.findAll(query, { skip, limit, sort }),
      WalletModel.countDocuments(query),
    ]);

    return {
      data,
      total,
      page,
      totalPages: Math.ceil(total / limit),
    };
  }
}

@Service()
export class WalletTransactionRepository extends BaseRepository<IWalletTransaction> {
  constructor() {
    super(WalletTransactionModel as Model<IWalletTransaction>);
  }

  private buildReferralRewardQuery(filter: WalletTransactionQueryParams = {}) {
    const query: any = {
      userId: filter.userId,
      transactionType: 'promotion',
      status: 'completed',
      referenceType: 'referral',
    };

    if (filter.transactionDateFrom || filter.transactionDateTo) {
      query.transactionDate = {};
      if (filter.transactionDateFrom) {
        query.transactionDate.$gte = filter.transactionDateFrom;
      }
      if (filter.transactionDateTo) {
        query.transactionDate.$lte = filter.transactionDateTo;
      }
    }

    return query;
  }

  async findByUserId(userId: string): Promise<IWalletTransaction[]> {
    return this.findAll({ userId }, { sort: { createdAt: -1 } });
  }

  async findByUserIdAndType(
    userId: string,
    transactionType: string
  ): Promise<IWalletTransaction[]> {
    return this.findAll(
      { userId, transactionType },
      { sort: { createdAt: -1 } }
    );
  }

  async findByReference(
    referenceType: string,
    referenceId: string
  ): Promise<IWalletTransaction[]> {
    return this.findAll(
      { referenceType, referenceId },
      { sort: { createdAt: -1 } }
    );
  }

  async findWithPagination(
    filter: WalletTransactionQueryParams = {},
    page: number = 1,
    limit: number = 10
  ): Promise<{
    data: IWalletTransaction[];
    total: number;
    page: number;
    totalPages: number;
  }> {
    const query: any = {};

    if (filter.userId) {
      query.userId = filter.userId;
    }

    if (filter.transactionType) {
      query.transactionType = filter.transactionType;
    }

    if (filter.status) {
      query.status = filter.status;
    }

    if (filter.referenceType) {
      query.referenceType = filter.referenceType;
    }

    if (filter.referenceId) {
      query.referenceId = filter.referenceId;
    }

    if (filter.transactionDateFrom || filter.transactionDateTo) {
      query.transactionDate = {};
      if (filter.transactionDateFrom) {
        query.transactionDate.$gte = filter.transactionDateFrom;
      }
      if (filter.transactionDateTo) {
        query.transactionDate.$lte = filter.transactionDateTo;
      }
    }

    const skip = (page - 1) * limit;
    const sort: any = {};

    if (filter.sortBy) {
      sort[filter.sortBy] = filter.sortOrder === 'desc' ? -1 : 1;
    } else {
      sort.createdAt = -1; // Most recent first
    }

    const [data, total] = await Promise.all([
      this.findAll(query, { skip, limit, sort }),
      WalletTransactionModel.countDocuments(query),
    ]);

    return {
      data,
      total,
      page,
      totalPages: Math.ceil(total / limit),
    };
  }

  async findReferralRewardsWithPagination(
    filter: WalletTransactionQueryParams,
    page: number = 1,
    limit: number = 10
  ): Promise<{
    data: IWalletTransaction[];
    total: number;
    page: number;
    totalPages: number;
  }> {
    const query = this.buildReferralRewardQuery(filter);
    const skip = (page - 1) * limit;
    const sort: any = {};

    if (filter.sortBy) {
      sort[filter.sortBy] = filter.sortOrder === 'desc' ? -1 : 1;
    } else {
      sort.createdAt = -1;
    }

    const [data, total] = await Promise.all([
      this.findAll(query, { skip, limit, sort }),
      WalletTransactionModel.countDocuments(query),
    ]);

    return {
      data,
      total,
      page,
      totalPages: Math.ceil(total / limit),
    };
  }

  async findReferralRewards(
    filter: WalletTransactionQueryParams = {}
  ): Promise<IWalletTransaction[]> {
    const query = this.buildReferralRewardQuery(filter);
    const sort: any = {};

    if (filter.sortBy) {
      sort[filter.sortBy] = filter.sortOrder === 'desc' ? -1 : 1;
    } else {
      sort.createdAt = -1;
    }

    return this.findAll(query, { sort });
  }

  async getReferralRewardSummary(
    filter: WalletTransactionQueryParams
  ): Promise<{ totalEarned: number; totalTransactions: number }> {
    const query = this.buildReferralRewardQuery(filter);
    const [summary] = await WalletTransactionModel.aggregate([
      { $match: query },
      {
        $group: {
          _id: null,
          totalEarned: { $sum: '$amount' },
          totalTransactions: { $sum: 1 },
        },
      },
    ]);

    return {
      totalEarned: summary?.totalEarned || 0,
      totalTransactions: summary?.totalTransactions || 0,
    };
  }

  async getLatestTransaction(userId: string): Promise<IWalletTransaction | null> {
    const transactions = await this.findAll(
      { userId },
      { sort: { createdAt: -1 }, limit: 1 }
    );
    return transactions.length > 0 ? transactions[0] : null;
  }
}
